pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below min item size is wasted forever
    } else if post_residual < 20 {
        score += 15.0; // near-dead gap: only items <= 19 can use it
    } else if post_residual <= 30 {
        score += 5.0;  // moderately awkward residual
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward gaps that can still host a typical future item.
    if post_residual >= 40 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into the resulting residual, favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless dead space would be created).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but allow the new-bin candidate (residual == capacity) to stay attractive.
    if bin_residual < bin_capacity {
        score += open_bins_count as f64 * 0.5;
    } else {
        // New bin candidate: neutral baseline, slightly above good fits.
        score += 2.0;
        // If existing bins would create dead space, make the new bin more attractive.
        if post_residual < 10 {
            score -= 10.0;
        }
    }

    // Late in the stream, tighten up: avoid leaving medium gaps that won't be filled.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 25 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += (10.0 - pr as f64) * 6.0; // dead space zone penalty
    }
    if pr == 0 {
        score -= 25.0; // perfect fit reward
    } else if pr <= 20 {
        score += 4.0; // mildly discourage near-dead gaps
    }

    // Reward bins whose residual tightly matches the item (good fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 8.0;

    // Open-bin pressure: discourage scattering across many bins unless fit is excellent.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // next item can't use the gap -> dead space likely
    }

    // New-bin candidate: prefer it only when all open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        // base preference for fresh bin scaled by mean residual of open bins
        score = 45.0 + mean_residual * 0.5 - (item_size as f64) * 0.3;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fits (small usable leftover) get a moderate reward, scaled by
    // how well the leftover could still host typical items.
    if post_residual >= 10 {
        score -= (bin_capacity as f64 - post_residual as f64) * 0.15;
    }

    // If the next item exactly fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if next item cannot fit the leftover (chain break risk).
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.6;

    // New-bin candidate: default neutral-ish, but allow it when the best
    // existing option would strand a large dead gap or when mean residual
    // across open bins is already tiny (all bins nearly full).
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.2;
        // If all open bins are nearly full, opening a new bin is fine.
        if mean_residual < 12.0 {
            score -= 20.0;
        }
        // Late in the stream, discourage spawning extra bins mildly.
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty scaled by how badly the residual fails to host the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0;
        } else {
            score += 14.0 + dead_ratio * 9.0;
        }
    }

    // Prefer bins where the item fills a large fraction of the residual.
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual.max(1) as f64);
        score -= ratio * 6.8 + ratio * ratio * 6.2;
    }

    // Waste created by this placement.
    let waste = bin_residual.saturating_sub(item_size);
    if waste > 0 {
        let w = waste as f64;
        score += if w < 6.0 { w * 0.3 } else { w.sqrt() * 1.45 };
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: exact fit for next item.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Near-exact lookahead fit.
    if post_residual > next_item_size && post_residual <= next_item_size + 7 && next_item_size > 0 {
        score -= 3.5 - (post_residual - next_item_size) as f64 * 0.15;
    }

    // Very tight near-fit: small slack is precious.
    if post_residual > next_item_size && next_item_size > 0 && post_residual - next_item_size <= 3 {
        score -= 2.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        let crowding = (open_bins_count as f64).ln().max(0.0);
        let mean_dead = mean_residual.max(0.0);
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5 + mean_dead * 0.08;
        } else {
            score -= 9.0 + tight * 12.0;
        }
        if step_index > total_items * 4 / 5 {
            score -= 6.0;
        }
    } else {
        score += open_bins_count as f64 * 0.5;
    }

    // Last-chance pressure: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // When few bins fit, discourage leaving a small slack for the next item.
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack >= 0.0 && slack < 12.0 {
            score += 9.0 - slack * 0.6;
        }
    }

    // Late-stream tightening: tiny residuals are nearly perfect fits late on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 25 {
        score += 10.0 * progress;
    }
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Combined lookahead: if this placement leaves residual exactly matching next item,
    // and the item itself nearly filled the bin, strongly reward the chain.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size && item_size >= bin_residual / 2 {
        score -= 12.0;
    }

    // Mean-residual coupling: when the fleet is broadly tight, prefer keeping residuals usable.
    if mean_residual > 0.0 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 && next_item_size > post_residual {
        score += 4.0;
    }

    // NEW: two-step lookahead chain — reward residuals that can host the next item
    // with a near-perfect follow-up, scaled by remaining stream length.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after <= 6 {
            let chain_bonus = 8.0 - after as f64 * 1.0;
            score -= chain_bonus * (1.0 - progress * 0.4);
        }
    }

    // NEW: penalize residuals that are just barely too small for the next item
    // (dead space that blocks chain packing), stronger early in the stream.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 8.0 {
            score += gap * (2.2 - progress * 0.8);
        }
    }

    // NEW: fleet-level pressure — when many bins are open, keep residuals
    // consolidated (avoid scattering small usable slacks across bins).
    if open_bins_count > 12 && post_residual > 0 && post_residual < 15 {
        score += ((open_bins_count - 12) as f64).min(10.0) * 0.35;
    }

    // NEW: mean-residual anchoring — prefer leaving residuals near the fleet mean
    // so future items have consistent landing zones.
    if mean_residual > 0.0 && post_residual > 0 {
        let drift = ((post_residual as f64) - mean_residual).abs();
        if drift < 8.0 {
            score -= (8.0 - drift) * 0.45;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance with dead-ratio scaling toward the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0;
        } else {
            score += 14.0 + dead_ratio * 9.0;
        }
    } else if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward gaps that can still host a typical future item.
    if post_residual >= 40 {
        score -= 8.0;
    }

    // Lookahead: exact match strongly favored; near-exact mildly favored.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 7.0 {
            score -= 10.0 - slack * 0.9;
        } else {
            score -= 6.0;
        }
    }

    // Fill-ratio coupling: prefer bins where the item tightly fills the residual.
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual.max(1) as f64);
        score -= ratio * 6.8 + ratio * ratio * 6.2;
    }

    // Waste shaping on the current bin.
    let waste = bin_residual.saturating_sub(item_size);
    if waste > 0 {
        let w = waste as f64;
        score += if w < 6.0 { w * 0.3 } else { w.sqrt() * 1.45 };
    }

    // Last-chance pressure: only fitting bin, avoid opening new bins.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // New-bin candidate logic: open a new bin only for large items or when
    // existing bins would create dead space.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        let crowding = (open_bins_count as f64).ln().max(0.0);
        let mean_dead = mean_residual.max(0.0);
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5 + mean_dead * 0.08;
        } else {
            score -= 9.0 + tight * 12.0;
        }
        if step_index > total_items * 4 / 5 {
            score -= 6.0;
        }
    } else {
        score += open_bins_count as f64 * 0.5;
    }

    // Tight-fit penalty when few fitting bins and slack small.
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack >= 0.0 && slack < 12.0 {
            score += 9.0 - slack * 0.6;
        }
    }

    // Late-stream tightening: small residuals become less valuable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 25 {
        score += 10.0 * progress;
    }
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Micro-slack lookahead bonus: near-exact next-item fits within 3 units.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        score -= 2.0;
    }

    // Mean-residual coupling: discourage dumping into an already-large gap.
    if post_residual > 0 && mean_residual > 0.0 && (post_residual as f64) > mean_residual * 1.6 {
        score += 3.0;
    }

    // NEW: pair-anticipation — reward residuals that can host the next item
    // plus a small follow-up, favoring bins that keep useful chains alive.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size + 8 {
        let chain_slack = (post_residual - next_item_size) as f64;
        if chain_slack <= 30.0 {
            score -= 4.0 * (1.0 - chain_slack / 30.0);
        }
    }

    // NEW: early-stream conservatism — avoid fragmenting space early.
    if step_index < total_items / 3 && post_residual > 0 && post_residual < item_size {
        score += 4.0;
    }

    score
}

