    // keeping tighter bins free) — but only when several bins are open.
    if open_bins_count > 2 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.08 * diff;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (cheap now, saves later); late in the stream, pack into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        // Base new-bin cost grows with progress (opening bins late is wasteful).
        score += 6.0 + 20.0 * progress;
