        score -= 0.3 * open_bins_count as f64;
        if mean_residual < 20.0 {
            score -= 8.0; // existing bins are nearly full; fresh bin is fine
        }
    } else {
        // Occupied bins get a discount late in the stream to avoid new bins.
        score -= 5.0 * progress;
    }

    // Slight preference for larger items entering emptier bins.
    score -= 0.02 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

