    // late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Penalize creating tiny unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild penalty for opening a brand-new bin when open bins exist and fit well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as u64 == bin_capacity as u64) as f64;

    // Base: post-residual, mildly de-emphasized late in the stream (tighten packing).
    let mut score = pr * (1.0 - 0.3 * progress);

    // Non-linear polynomial coupling of post_residual with progress.
    let prn = pr / cap;
    score += 8.0 * prn * prn * (0.5 + progress) * cap * 0.1;
    score -= 4.0 * prn * (1.0 - prn) * (1.0 - progress);

    // Penalize dead space (small post residual) late in stream.
    score += (1.0 - prn).powi(3) * 3.0 * progress;

    // New-bin candidate: penalize early, allow late when residuals are poor.
    let mean_res_n = mean_residual / cap;
    score += is_new_bin * (10.0 - 8.0 * progress * (1.0 - mean_res_n));

    // Last-chance bonus: only one fitting bin.
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 6.0;
    }

    // Lookahead coupling: reward leaving space for next item.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        score -= fit_next * (1.0 + progress) * 2.0;
        score += (nxt / cap) * (1.0 - fit_next) * 4.0;
    }

    // Penalize many open bins slightly (bin consolidation pressure).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a fresh bin unless the fit here is bad
    // or this bin is a "last chance" that would leave dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 40.0;
        // Last-chance bins with a decent fit should be preferred over a new bin.
        if fitting_bins_count == 1 && post_residual <= 10 {
            penalty += 60.0;
        }
        // Small items open new bins more freely (they leave usable space).
        if item_size <= 30 {
            penalty -= 15.0;
        }
        score += penalty;
    } else {
        // Reward tight fits strongly.
        score -= (bin_residual - post_residual) as f64 * 0.25;

        // Dead-space penalty: residual that cannot fit typical future items.
        if post_residual < 10 {
            score += 25.0; // nearly full: fine, minimal waste
        } else if post_residual < 20 {
            score -= 10.0; // good saturation
        } else {
            // Harmonic class of the leftover: which "item classes" can still use it?
            let usable_classes = (post_residual / 10).min(8) as f64;
            score -= usable_classes * 2.0;
        }

        // Modulo classes on post_residual: leftovers near multiples of common
        // item sizes (10, 20, 25) are more likely to be filled later.
        let pr = post_residual;
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 25 == 0 || pr % 20 == 0 {
            score -= 4.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        } else {
            score += 3.0; // awkward leftover
        }

        // Lookahead coupling: does this placement still allow the next item?
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 8.0;
                // Bonus if post_residual is an exact harmonic match for next item.
                if post_residual == next_item_size {
                    score -= 12.0;
                }
            } else {
                // Penalize blocking the next item unless another bin can take it.
                score += 5.0;
                if fitting_bins_count == 1 {
                    score += 10.0;
                }
            }
        }

        // Last-chance dynamics: strongly prefer using the only fitting bin
        // when the fit is reasonable, to avoid bin proliferation.
        if fitting_bins_count == 1 && post_residual <= 30 {
            score -= 15.0;
        }

        // Stream phase: early on, keep bins balanced (favor residual near mean);
        // late, greedily fill the fullest bins.
        let phase = step_index as f64 / total_items.max(1) as f64;
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * (0.15 * (1.0 - phase) - 0.05 * phase);

        // Many open bins: discourage leaving medium-large residuals scattered.
        if open_bins_count > 6 && post_residual > 40 {
            score += (open_bins_count as f64 - 6.0) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that is too small to hold even the smallest plausible item
    // (or the known next item) is wasted space.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size) {
        score += 40.0;
    }
    // Penalize any post_residual below the next item size less harshly but still visibly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual == next_item_size && next_item_size > 0 {
        // Gap exactly fits the lookahead item: excellent.
        score -= 20.0;
    }

    // Reward tight fits relative to item size (small waste ratio).
    if item_size > 0 {
        score -= (item_size as f64) / (bin_residual.max(1) as f64) * 8.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and prefer consolidating into existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 12.0 + (open_bins_count as f64) * 2.5;
        // But if no existing bin fits well (this is the last fitting bin and it's tight),
        // a new bin may be preferable; soften penalty.
        if fitting_bins_count <= 1 && post_residual < item_size as u32 / 2 {
            score -= 18.0;
        }
    } else {
        // Existing bin: reward being chosen, more so when many bins are open.
        score -= (open_bins_count as f64) * 1.2;
        // Last-chance bin: strong bonus to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., fuller bins), reducing fragmentation across the fleet.
    score += (bin_residual as f64 - mean_residual) * 0.35;

    // Slight stream progression term: later in the stream, be more conservative
    // about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already base score).
    // 2-step lookahead: reward if the NEXT item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: next item seals this bin
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (slack_after_next as f64 / bin_capacity as f64);
            if slack_after_next < 10 {
                score -= 15.0; // near-perfect chain
            }
        } else {
            // next item won't fit here; penalize proportionally to the mismatch
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss.min(40.0);
        }
    }

    // Penalize creating dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: bins with less residual than average
    // are "darker" — prefer filling them first to consolidate space.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild pressure to close bins early in the stream; slight openness later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();

    // Prefer bins that are already heavily loaded (waste-aware).
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that becomes unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits perfectly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            score += 5.0;
        }
    }

    // New-bin candidate handling: make empty bins less attractive unless
    // current bin would leave a bad gap or the item barely fits nothing.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: mild, so it loses to decent fits.
        score += 15.0;
        // But if item is large relative to mean residual, opening fresh is fine.
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins that are already low on residual (consolidation).
    let filled = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * filled;

    // Mild penalty for using many open bins: encourage closing bins out.
    score += 0.3 * open_bins_count as f64;

    // Slight pull toward bins near the mean residual (balanced packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual penalized more as stream advances
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-shaped base
    score += poly * cap * (0.5 + progress);

    // Interaction: post_residual * progress^2 (late-stream dead space penalized harder)
    score += 8.0 * pr * progress * progress;

    // Reward tight fits (small post residual) with a smooth quadratic bonus
    score -= 12.0 * (1.0 - x) * (1.0 - x);

    // Last-chance bin: smooth exponential urgency growing with progress
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress * progress);
    }

    // Lookahead coupling: if next item fits exactly into post residual, reward smoothly
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (-gap / 20.0) * (1.0 + progress);
    }

    // Penalize bins far below mean residual (fragmentation pressure), smooth in progress
    score += 0.05 * (mean_residual - pr).abs() * (0.5 + progress);

    // Mild penalty for many open bins, smoothed by progress
    score += open_bins_count as f64 * (0.2 + 0.8 * progress);

    // New-bin candidate: make it attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        score -= 5.0 + 10.0 * progress * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "useful" residue classes (multiples of common small item sizes) are favored.
    let cap = bin_capacity as f64;

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Class-based dead-space penalty: leftover in (0,10] is nearly unusable
    // since min item size historically ~10; but interface allows 1..100.
    if post_residual > 0 && post_residual < 5 {
        score += 80.0; // tiny dead sliver
    }

    // Harmonic bucketing of post_residual by integer division thresholds.
    let bucket = post_residual / 10; // 0..10 buckets
    score += bucket as f64 * 3.0;

    // Residue-class bonus: leftover divisible by 25 or 50 pairs well with
    // medium items; reward such "harmonic" leftovers.
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 25.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 40.0 - (slack as f64).min(40.0); // better when slack small
            // harmonic match: next item leaves a multiple-of-10 residue
            if slack % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize slightly less if residual
            // still useful for typical small items
            if post_residual >= 20 {
                score += 5.0;
            } else {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate logic: prefer opening a fresh bin only when the item
    // is large relative to capacity or all open residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        // large items like fresh bins; small items should use open space
        let fresh_bonus = 120.0 * item_frac - 60.0;
        score -= fresh_bonus;
        // late in stream, consolidating is better than sprawling
        score += 40.0 * progress;
        // many open bins with high mean residual -> use them instead
        if mean_residual > item_size as f64 {
            score += 30.0;
        }
    }

    // Mild pressure to keep number of open bins low.
    score += open_bins_count as f64 * 0.5;

    // Slight tie-break toward bins with residual close to item (best-fit core).
    score += ((bin_residual - item_size) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 10 {
        // small unusable gap: heavy penalty proportional to wasted space pressure
        score += (11 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        score += (21 - post_residual) as f64 * 2.0;
    }

    // Reward exact-ish fits more strongly.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // creating a gap that the next item cannot use
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Mean-residual coupling: if this bin is far below mean residual (already tight),
    // placing here wastes little; if far above mean, penalize lightly.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference to fill older/tighter bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_reward = 40.0_f64.max(0.0) - diff.min(60.0);
        score -= match_reward;
        // Perfect chain: post_residual exactly equals next item size -> huge bonus.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: minimize waste directly.
        score += post_residual as f64 * 0.5;
    }

    // Penalize unusable dead space: residuals too small for the smallest item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Penalize large leftover beyond what next item can absorb.
    if next_item_size > 0 && post_residual > next_item_size {
        score += (post_residual - next_item_size) as f64 * 0.3;
    }

    // Last-chance bin: this is the only bin that fits; strongly prefer it over new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if current bin fit is poor (large post_residual waste
    // relative to mean residual) or bin is already tight-ish; otherwise discourage.
    if bin_residual == bin_capacity {
        let mean_fit_gap = (bin_capacity as f64 - item_size as f64) - mean_residual;
        let poor_fit = post_residual as f64 - mean_residual;
        if poor_fit > 0.0 && mean_fit_gap < 0.0 {
            score -= 20.0; // open a fresh bin rather than waste residual space
        } else {
            score += 15.0; // prefer reusing an existing fitting bin
        }
    }

    // Mild pressure toward filling bins tighter as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.1 + 0.2 * progress);

    // Prefer bins below mean residual (tighter bins) slightly.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(3);

    // Penalize dead space that no future item can plausibly use.
    // Items are between 1 and 100; residual smaller than the smallest plausible item is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.25 * next_item_size as f64;
        } else {
            // Wasted potential if next item is close to fitting but not quite.
            let gap = (next_item_size as f64 - post_residual as f64).min(30.0);
            score += 0.4 * gap;
        }
    } else {
        // Last item: just minimize post_residual, no future to serve.
        score -= 10.0;
    }

    // Time horizon: early in the stream, be more willing to fragment (spread items);
    // late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 8.0 * tightness;
    score -= progress * 12.0 * tightness;

    // Global state: many open bins with high mean residual -> prefer reusing fuller bins
    // (bin with small residual) to consolidate, avoid bin proliferation.
    if open_bins_count > 2 && mean_residual > 30.0 {
        score += 0.15 * mean_residual * tightness;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to capacity or all open bins are poor fits.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base penalty so new bins are not opened casually.
        score += 55.0;
        // Reward opening a new bin for large items or when no bin fits.
        score -= 45.0 * item_frac * item_frac;
        score -= 60.0 * desperation;
        // Late in the stream, avoid opening new bins.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted residual, normalized
    let mut score = pr / c;

    // Smooth polynomial coupling: waste penalty grows super-linearly with progress
    let waste = pr / c;
    score += 2.0 * waste * waste * (0.5 + progress);

    // Tight fit reward: smooth bump around post_residual near 0
    let tight = 1.0 - (pr / c);
    score -= 1.5 * tight * tight * tight * (it / c);

    // Reward using nearly-full bins (low residual relative to capacity)
    let fullness = 1.0 - (br / c);
    score -= 0.8 * fullness * fullness;

    // Last-chance bonus: smooth interaction with fitting bins count
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - progress) * (1.0 - progress);
    }

    // Lookahead: penalize if post_residual can't fit next item (smooth quadratic)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = ((ns - pr) / c).max(0.0);
        score += 0.6 * gap * gap;
        // Reward if next item fits smoothly into post residual
        let fit_next = ((pr - ns) / c).max(0.0);
        score -= 0.4 * fit_next * (1.0 - fit_next);
    }

    // Mild penalty for too many open bins, smoothed
    score += 0.02 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins near mean (smooth quadratic)
    let dev = (pr - mean_residual) / c;
    score += 0.3 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect harmony, huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead space classes are bad.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction remaining

    // Penalize residual classes that are hard to fill (mod-10 dead zones).
    let class = post_residual % 10;
    score += match class {
        0 => -20.0,   // clean multiple of 10: desirable
        1..=5 => 15.0 + 3.0 * class as f64, // tiny slivers: dead space
        _ => 5.0,     // medium leftovers: mediocre
    };

    // Integer-division thresholds on post_residual.
    let q = post_residual / 25; // quarters of capacity
    score += match q {
        0 => 30.0,               // < 25 left: nearly dead bin
        1 => 10.0,               // 25..49
        2 => 0.0,                // 50..74
        _ => -10.0,              // >= 75: roomy
    };

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves a residue: mild reward scaled by tightness
        let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 40.0 * tight;
    } else if next_item_size > post_residual {
        // next item won't fit here: penalize small post_residuals more
        score += 25.0 * (1.0 - frac);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // unless post_residual would be a tiny useless sliver.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
        if post_residual > 0 && post_residual < 10 {
            score += 40.0; // still avoid creating micro-slivers
        }
    }

    // New-bin candidate logic: empty bin should win only when all open fits are bad.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: slightly worse than a good fit, better than a bad one.
        score = 55.0;
        // If many bins are open and mean residual is large, prefer reusing bins.
        score += 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 20.0;
        }
        // If next item is huge and current item is small, opening fresh can be smart.
        if next_item_size > 60 && item_size < 30 {
            score -= 30.0;
        }
    }

    // Progress coupling: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * frac; // late stream: penalize leaving big residuals
    score -= progress * 5.0;         // late stream: slight bias to fill existing bins

    // Mean-residual coupling: prefer bins below mean residual (fill emptier-of-space bins? no:
    // prefer bins whose residual is close to item size, i.e., tight fits).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual <= 30 {
        score += 5.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward gaps that can still host a typical future item.
    if post_residual >= 40 {
        score -= 8.0;
    }

    // Lookahead: exact fit for next item strongly favored.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // gap too small for the known next item
    }

    // Tight-fill reward: prefer bins whose residual is mostly consumed by this item.
    if item_size > 0 && bin_residual > 0 {
        score -= (item_size as f64) / (bin_residual as f64) * 8.0;
    }

    // Mean residual coupling: prefer fuller bins relative to the fleet average.
    score += (bin_residual as f64 - mean_residual) * 0.35;

    // Last-chance pressure: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // Open-bin pressure with fleet-aware scaling.
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 1.2;
    } else {
        // New-bin candidate: penalize more when many bins already open.
        score += 12.0 + open_bins_count as f64 * 2.5;
        // Soften if existing fits would create dead space.
        if post_residual < 10 {
            score -= 10.0;
        }
        // Late-stream conservatism: opening bins late is costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    }

    // Late-stream tightening of medium gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 25 {
        score += 10.0 * progress;
    }

    score
}

