        score -= 22.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size * 2 {
        // Gap can hold the next item with modest slack: still good.
        score -= 6.0;
    }

    // Tight-fit reward relative to item size, non-linear (quadratic waste ratio).
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual.max(1) as f64);
        score -= ratio * 6.0 + ratio * ratio * 3.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
