        let mut penalty = 14.0 + (open_bins_count as f64) * 2.2;
        // Lookahead: if the next item is large and no open bin could take both
        // this item and the next, opening a fresh bin is attractive.
        if next_item_size > 0 {
            let paired = item_size.saturating_add(next_item_size);
            if paired >= bin_capacity {
                penalty -= 10.0;
            }
        }
        // If only one open bin fits and the fit is loose (large waste),
        // a new bin may be preferable.
        if fitting_bins_count <= 1 {
            let waste = bin_residual.saturating_sub(item_size);
            if waste > item_size * 2 {
                penalty -= 12.0;
            }
        }
        // Late in the stream, be more conservative about new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty += progress * 7.0;
        score += penalty;
    } else {
        // Existing bin: reward consolidation, stronger with more open bins.
        score -= (open_bins_count as f64) * 1.4;
        // Last-chance bin: strong bonus to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 12.0;
