        // Perfect-fit-in-progress: residual exactly equals next item after placement.
        if post_residual == next_item_size && next_item_size > 0 {
            score -= 5.0;
        }
    }

    // Fuller-than-average bins are preferred (fragmentation control).
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Slight bonus for bins whose residual is a "friendly" size for typical items.
    if post_residual >= 30 && post_residual <= 70 {
        score -= 2.0;
    }

    score
}

