        let ratio = (item_size as f64) / (bin_residual.max(1) as f64);
        score -= ratio * 6.0 + ratio * ratio * 4.5;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Scarcity coupling: when few bins can host, keep flexible residuals.
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack >= 0.0 && slack < 10.0 {
            score += 7.0 - slack * 0.5;
        }
    }

    // Consolidation: prefer bins below mean residual, scaled by progress.
    if bin_residual < bin_capacity && open_bins_count > 2 {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= dev * (0.12 + 0.08 * progress);
        }
    }

    // New-bin arbitration: open a fresh bin only when fits are poor or bins crowded.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if fitting_bins_count > 1 && tight < 0.58 {
            score += 30.0 + (0.58 - tight) * 45.0 + 12.0 * progress;
        } else {
            score -= 8.0 + tight * 10.0;
            if mean_residual < 20.0 {
                score -= 6.0;
            }
        }
    } else {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    // Late-stream near-perfect fill bonus.
    if post_residual > 0 && post_residual <= 3 && step_index > total_items * 3 / 4 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
