    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness;

    // Perfect fit: extreme reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are still useful; encourage using existing bins.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin's post-fit residual
    // is unusable for the next item and mean residual across bins is high.
    if bin_residual == bin_capacity {
        let dead_next = next_item_size > 0 && post_residual < next_item_size as f64;
        if dead_next || mean_residual < item_size as f64 * 0.5 {
            score -= 20.0 + 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        } else {
