        if fitting_bins_count > 2 && next_item_size > 0 && next_item_size <= post_residual.max(next_item_size) {
            score += 5.0;
        }
    }

    // Open-bin pressure.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward placements that leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        if post_residual == next_item_size {
            score -= 13.0;
        }
        let slack = post_residual as f64 - next_item_size as f64;
        if fitting_bins_count <= 2 && slack < 12.0 {
            score += 9.0 - slack * 0.6;
        }
        if slack > 0.0 && slack <= 3.0 {
            score -= 2.0;
        }
        if slack > 3.0 && slack <= 7.0 {
            score -= 3.5 - slack * 0.15;
        }
        if slack > 7.0 && slack <= 14.0 && post_residual < 30 {
            score -= (14.0 - slack) * 0.35;
        }
        // Two-item lookahead: chained perfect fits.
        let after = post_residual - next_item_size;
        if after == 0 {
            score -= 6.0;
        } else if after <= 2 {
            score -= 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0;
        } else {
            score += 14.0 + dead_ratio * 9.0;
        }
    }

    // Mean-residual coupling: prefer tighter bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference to fill older/tighter bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Late-stream small-residual bonuses.
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Residual-fraction fit term — reward placements that consume a large
    // fraction of the residual, penalize tiny bites of large residuals.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let frac = (item_size as f64) / (bin_residual as f64);
        if frac >= 0.9 {
            score -= 5.0;
        } else if frac < 0.25 {
            score += (0.25 - frac) * 22.0;
        }
    }

    // Dead-space ratio lookahead — if the leftover after this placement
    // cannot fit the next item, penalize proportionally to how much is wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let unusable = post_residual as f64 / next_item_size.max(1) as f64;
        if unusable < 0.35 {
            score += 18.0 * (0.35 - unusable);
        }
    }

    // Late-stream consolidation — with few items left, prefer closing
    // bins with near-perfect fills more aggressively.
    let remaining = total_items.saturating_sub(step_index);
    if remaining <= 12 && post_residual > 0 {
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity.max(1) as f64;
        score -= fill * 4.0;
    }

    // NEW: exact-slack coupling — when the post-fit slack equals a small
    // multiple of typical item granularity, strongly reward closing the bin.
    if next_item_size > 0 && post_residual > 0 {
        let d = post_residual as i64 - next_item_size as i64;
        if d == 0 {
            score -= 4.0;
        } else if d == 1 || d == 2 {
            score -= 2.5;
        }
    }

    // NEW: crowding-aware consolidation — when many bins are open, tighten
    // the preference for bins that will end up with small residuals, pushing
    // toward fewer open bins overall.
    if open_bins_count > 6 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr <= 15.0 {
            score -= (15.0 - pr) * 0.9;
        } else if pr > 45.0 {
            score += (pr - 45.0) * 0.35;
        }
    }

    // NEW: next-item dual-fit lookahead — if the residual after this placement
    // can hold the next item almost exactly, or the next item would leave a
    // tiny remainder itself, prefer this bin.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 3 && fitting_bins_count <= 3 {
            score -= 3.0;
        }
        if next_item_size <= bin_capacity {
            let after2 = after as i64 - next_item_size as i64;
            if after2 >= 0 && after2 <= 2 {
                score -= 4.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).

    // Dead-space penalty: super-linear in wasted space, but only for
    // residuals too small to hold typical future items.
    let dead_threshold = 25.0;
    if (post_residual as f64) > dead_threshold {
        score += 0.35 * (post_residual as f64 - dead_threshold);
    }

    // Lookahead bonus: if the next item fits exactly-ish into post_residual,
    // strongly reward this placement (chaining two items in one bin).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.25 * chain_waste;
        } else if post_residual == 0 {
            // Perfect closure of the bin is always excellent.
            score -= 15.0;
        }
    } else {
        // Last item: any nonzero residual is pure waste.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, modulated by stream position
        // and how fragmented the current bins are.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 45.0 + 30.0 * progress + 0.4 * fragmentation;
        // Late in the stream, or when few bins fit, opening a new bin is cheap.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can chain the next item too
        }
    }

    // Mild tie-breaker: spread load when many bins are open and residuals
    // are high (avoid hoarding into one bin).
    if open_bins_count > 3 && mean_residual > 40.0 {
        score += 0.05 * (post_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;

    // Dead-space penalty for the lookahead item (refined tiers)
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size . max (1) as f64 ;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0 ;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0 ;
        } else {
            score += 14.0 + dead_ratio * 9.0 ;
        }
    }

    // Best-fit pressure with non-linear fill term (blended coefficients)
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual . max (1) as f64) ;
        score -= ratio * 7.1 + ratio * ratio * 6.8 ;
    }

    // Waste penalty with mild convexity
    let waste = bin_residual . saturating_sub (item_size) ;
    if waste > 0 {
        let w = waste as f64 ;
        score += if w < 6.0 { w * 0.3 } else { w . sqrt () * 1.45 } ;
    }

    // Exact-fill lookahead bonus (strengthened)
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0 ;
    }
    // Near-miss lookahead
    if post_residual > next_item_size && post_residual <= next_item_size + 7 && next_item_size > 0 {
        score -= 3.5 - (post_residual - next_item_size) as f64 * 0.15 ;
    }
    // Chain lookahead
    if post_residual > next_item_size && next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
        score -= 4.0 ;
    }

    // New-bin arbitration with crowding pressure
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity . max (1) as f64) ;
        let crowding = (open_bins_count as f64) . ln () . max (0.0) ;
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5 ;
        } else {
            score -= 9.0 + tight * 12.0 ;
        }
        // Late-stream new bins are cheaper than fragmenting
        if step_index > total_items * 4 / 5 {
            score -= 6.0 ;
        }
    }

    // Scarcity coupling
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64 ;
        if slack >= 0.0 && slack < 12.0 {
            score += 9.0 - slack * 0.6 ;
        }
    }

    // Global compaction term, progress-scaled
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64 ;
        if dev > 0.0 {
            let progress = (step_index as f64) / (total_items . max (1) as f64) ;
            score -= dev * (0.18 + 0.18 * progress) ;
        }
    }

    // Late-stream exact-fill bonus (extended range, best-heuristic variant)
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0 ;
    }

    // Early tiny residual penalty
    if post_residual > 0 && post_residual < 6 && step_index <= total_items / 2 {
        score += 3.5 ;
    }

    // Late-stream squeeze: prefer near-full bins when nearing the end
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4 ;
    }

    // Fragmentation guard
    if open_bins_count > 8 && post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 5.0 ;
    }

    // Two-step lookahead: reserve bins whose residual fits the next item exactly
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        score -= 2.8 ;
    }

    // Perfect-fill dominant bonus: near-exact fits are strongly preferred
    if post_residual > 0 && post_residual <= 2 {
        score -= 4.0 ;
    }

    // Mid-stream pairing: prefer bins that can host the next item with a small remainder
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && step_index < total_items * 3 / 5 {
        score -= 1.5 ;
    }

    // NEW: wide-lookahead pairing — bins leaving room for the next item with modest slack
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 14 {
        let slack = (post_residual - next_item_size) as f64 ;
        let progress = (step_index as f64) / (total_items . max (1) as f64) ;
        score -= (14.0 - slack) * (0.10 + 0.10 * progress) ;
    }

    // NEW: avoid leaving residuals just below common mid-range items
    if post_residual > 0 && post_residual < 40 && next_item_size > post_residual {
        score += (40 - post_residual) as f64 * 0.08 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with quadratic sharpening.
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them more strongly.
    let progress_coupling = 1.0 + 1.5 * progress * progress + 0.8 * progress;
    score *= progress_coupling;

    // Cubic interaction: residual waste squared vs. progress — dead space matters more near the end.
    score += 0.5 * norm_pr * norm_pr * norm_pr * (progress * 3.0 + 0.5);

    // Fit tightness relative to mean residual: bins far below mean residual are precious.
    let mean_norm = mean_residual / cap;
    let tightness = (mean_norm - norm_pr).max(0.0);
    score -= 0.6 * tightness * (1.0 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 + 1.0 * progress;
    }

    // Lookahead: reward if next item fits into the post residual smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // next item fits: reward, scaled by how well it fills the leftover
            let fill = nx / pr.max(1.0);
            score -= 0.8 * fill * fill * (1.0 + progress);
        } else {
            // next item cannot fit: penalize leftover that is almost-but-not-quite usable
            let gap = (nx - pr) / cap;
            score += 0.4 * gap * (1.0 - progress);
        }
    }

    // New-bin candidate handling: mildly discourage opening new bins when good fits exist,
    // but allow it early in the stream or when residuals across bins are already fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64).max(1.0).ln();
        score += 1.2 + 0.5 * fragmentation - 0.6 * progress;
    }

    // Mild penalty for spreading across many open bins (encourages consolidation).
    score += 0.02 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits via non-linear shaping.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity.max(1) as f64);
    score -= 18.0 * tightness * tightness;

    // Dead-space penalty: leftover too small to fit the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0;
        } else {
            score += 14.0 + dead_ratio * 9.0;
        }
    }

    // Waste shaping on remaining slack after placement (sqrt sublinear).
    let waste = bin_residual.saturating_sub(item_size);
    if waste > 0 {
        let w = waste as f64;
        score += if w < 6.0 { w * 0.3 } else { w.sqrt() * 1.45 };
    }

    // Lookahead: exact fit for next item is highly valuable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 13.0;
        } else if post_residual > next_item_size && post_residual <= next_item_size + 7 {
            score -= 3.5 - (post_residual - next_item_size) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer emptier bins absorbing items when many bins are open.
    if open_bins_count > 2 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.08 * diff;
    }

    // New-bin decision: open a fresh bin only when existing fits are poor
    // (small item relative to capacity) or bins are crowded.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        let crowding = (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5;
        } else {
            score -= 9.0 + tight * 12.0;
        }
        if step_index > total_items * 4 / 5 {
            score -= 6.0;
        }
    }

    // Late-stream salvage of tiny residuals.
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Slight preference for larger items entering emptier bins.
    score -= 0.02 * item_size as f64 * (bin_residual as f64 / bin_capacity.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue classes" are wasteful; reward residues that pair well
    // with common item sizes (multiples of 10, and small leftovers).
    let cap = bin_capacity as f64;

    // Class A: post_residual is an exact harmonic multiple (10, 20, ...) -> highly reusable
    let pr = post_residual;
    if pr > 0 && pr % 10 == 0 {
        score -= 6.0;
        if pr % 20 == 0 { score -= 2.0; }
        if pr % 25 == 0 { score -= 1.5; }
    }

    // Class B: dead space — residual too small for the smallest plausible item
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Integer-division threshold: post_residual / item_size ratio classes
    let fill_ratio = item_size as f64 / cap;
    score -= 10.0 * fill_ratio; // reward tight fits (large item in this bin)

    // Lookahead coupling: harmonic class of next item vs this bin's post residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: strong reward, scaled by how "classy" the fit is
            score -= 5.0;
            if (pr - next_item_size) % 10 == 0 { score -= 3.0; }
            if pr % 10 == next_item_size % 10 { score -= 1.0; }
        } else {
            // next item cannot use this bin's leftover: penalize leftover size
            score += 0.02 * pr as f64;
        }
        // next item is harmonic (multiple of 10): leftover of same class is prime
        if next_item_size % 10 == 0 && pr >= next_item_size {
            score -= 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // unless it would create dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if pr < 10 && pr > 0 {
            score += 3.0; // but not if it makes dead space
        } else {
            score -= 7.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is only good when the
    // item is large (harmonic-large class) or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size >= 50;
        if !large_item && fitting_bins_count >= 1 && pr >= 0 {
            // prefer existing bins for small/medium items
            score += 12.0;
        }
        if large_item {
            score += 4.0; // slight penalty; existing near-full bins still better
        }
        // late in the stream, avoid spawning bins with tiny expected future use
        score += 5.0 * progress;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // already "harmonically spent" — placing here consolidates waste.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual - cap * 0.3 {
        score -= 2.0;
    } else if residual_f > mean_residual + cap * 0.3 {
        score += 2.0;
    }

    // Open bins pressure: many open bins -> consolidate into existing ones.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Compare against mean residual: bins with residual below mean are "denser";
    // favor placing into them to consolidate space.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Lookahead: if the next item could exactly use the post residual,
    // strongly reward leaving that gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // gap too small for next item -> dead space risk
        score += 10.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., all fits are loose) — keep its score moderate otherwise.
    if bin_residual == bin_capacity {
        let best_possible_waste = if fitting_bins_count == 0 { 0.0 } else { 12.0 };
        score = 100.0 + best_possible_waste - (fitting_bins_count as f64) * 20.0;
        if fitting_bins_count == 1 {
            score += 60.0; // never open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: gaps too small to be useful are worthless.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 10 {
        score += (11 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        score += (21 - post_residual) as f64 * 2.0;
    }

    // Fit-quality coupling: reward tight fills relative to remaining space.
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual.max(1) as f64);
        score -= ratio * 6.8 + ratio * ratio * 6.2;
    }

    // Waste penalty (non-linear).
    let waste = bin_residual.saturating_sub(item_size);
    if waste > 0 {
        let w = waste as f64;
        score += if w < 6.0 { w * 0.3 } else { w.sqrt() * 1.45 };
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        let crowding = (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5;
        } else {
            score -= 9.0 + tight * 12.0;
        }
        if step_index > total_items * 4 / 5 {
            score -= 6.0;
        }
        if fitting_bins_count > 2 && next_item_size > 0 && next_item_size <= post_residual.max(next_item_size) {
            score += 5.0;
        }
    }

    // Open-bin pressure.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward placements that leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        if post_residual == next_item_size {
            score -= 13.0;
        }
        let slack = post_residual as f64 - next_item_size as f64;
        if fitting_bins_count <= 2 && slack < 12.0 {
            score += 9.0 - slack * 0.6;
        }
        if slack > 0.0 && slack <= 3.0 {
            score -= 2.0;
        }
        if slack > 3.0 && slack <= 7.0 {
            score -= 3.5 - slack * 0.15;
        }
        if slack > 7.0 && slack <= 14.0 && post_residual < 30 {
            score -= (14.0 - slack) * 0.35;
        }
        // Two-item lookahead: chained perfect fits.
        let after = post_residual - next_item_size;
        if after == 0 {
            score -= 6.0;
        } else if after <= 2 {
            score -= 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0;
        } else {
            score += 14.0 + dead_ratio * 9.0;
        }
        // Unusable-slant penalty: tiny leftovers that cannot fit the next item.
        let unusable = post_residual as f64 / next_item_size.max(1) as f64;
        if unusable < 0.35 {
            score += 18.0 * (0.35 - unusable);
        }
    }

    // Mean-residual coupling: prefer tighter bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference to fill older/tighter bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Late-stream small-residual bonuses.
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Residual-fraction fit term — reward near-exact fills, penalize tiny bites.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let frac = (item_size as f64) / (bin_residual as f64);
        if frac >= 0.9 {
            score -= 5.0;
        } else if frac < 0.25 {
            score += (0.25 - frac) * 22.0;
        }
    }

    // Late-stream consolidation — prefer closing bins with near-perfect fills.
    let remaining = total_items.saturating_sub(step_index);
    if remaining <= 12 && post_residual > 0 {
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity.max(1) as f64;
        score -= fill * 4.0;
    }

    // NEW: slack-band sharpening — reward leaving exactly a small usable
    // remainder for the next item, with a tighter window than before.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 2.0 {
            score -= 2.5;
        } else if gap <= 5.0 {
            score -= 1.2;
        }
    }

    // NEW: early-stream bin conservation — avoid opening new bins too eagerly
    // while many items remain, unless the fit is very tight.
    if bin_residual == bin_capacity && remaining > 40 && fitting_bins_count >= 1 {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        if tight < 0.35 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Reward near-perfect lookahead fits (small gap).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= (10.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
