    else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight packing relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer filling existing bins over opening new ones, especially late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, more so as stream progresses.
        score += 15.0 + 25.0 * progress;
    } else {
        score -= 2.0;
    }

    // Slight penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize exact-ish fits that leave dead space < next item's need? Reward instead.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus when leftover can host the lookahead item
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize leftovers too small for the next item (dead space)
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
