        // Last item: prefer tightest fit aggressively
        score -= 20.0 * (1.0 - fit_ratio);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread_penalty = (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    score += 2.0 * spread_penalty;

    // Bin much emptier than average: slight penalty (prefer bins closer to being full)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate: penalize unless current bin would leave unusable sliver
    if bin_residual == bin_capacity {
        let sliver = (bin_residual - item_size) as f64;
        if next_item_size > 0 && sliver > 0.0 && sliver < next_item_size as f64 {
