        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        if post_class == next_class {
            score -= 6.0; // same harmonic class bonus
        }
    } else if next_item_size > post_residual {
        // next item can't use this residual: penalize proportionally to wasted class
        score += 8.0 * (post_class as f64) * (next_item_size as f64 / bin_capacity as f64);
    }

    // Dead-space penalty: small unusable residuals
    if post_residual < 10 {
        score += 15.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Integer division threshold on post_residual: perfect fits
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize spreading across many open bins lightly
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

