    // Reward bins whose residual tightly matches the item (good fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 8.0;

    // Open-bin pressure: discourage scattering across many bins unless fit is excellent.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // next item can't use the gap -> dead space likely
    }

    // New-bin candidate: prefer it only when all open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        // base preference for fresh bin scaled by mean residual of open bins
        score = 45.0 + mean_residual * 0.5 - (item_size as f64) * 0.3;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item exactly fills this bin's post-residual (perfect 2-step match).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)) * (post_residual as f64 / bin_capacity as f64);
        // Penalize post-residuals that are small but nonzero (unusable dead space).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: prefer minimal waste.
        score += 0.0;
    }

    // Compare against mean residual: favor bins with below-average residual (tighter packing).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so we prefer good fits into open bins,
    // but allow opening when residuals are large/fragmented.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;

    // Dead-space penalty for the lookahead item (refined tiers)
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size . max (1) as f64 ;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0 ;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0 ;
        } else {
            score += 14.0 + dead_ratio * 9.0 ;
        }
    }

    // Best-fit pressure with non-linear fill term (combined tuning)
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual . max (1) as f64) ;
        score -= ratio * 7.0 + ratio * ratio * 6.6 ;
    }

    // Waste penalty with mild convexity (softer on tiny waste)
    let waste = bin_residual . saturating_sub (item_size) ;
    if waste > 0 {
        let w = waste as f64 ;
        score += if w < 6.0 { w * 0.3 } else { w . sqrt () * 1.45 } ;
    }

    // Exact-fill lookahead bonus
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 13.0 ;
    }
    // Near-miss lookahead
    if post_residual > next_item_size && post_residual <= next_item_size + 7 && next_item_size > 0 {
        score -= 3.5 - (post_residual - next_item_size) as f64 * 0.15 ;
    }
    // Chain lookahead
    if post_residual > next_item_size && next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
        score -= 4.0 ;
    }

    // New-bin arbitration with crowding pressure
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity . max (1) as f64) ;
        let crowding = (open_bins_count as f64) . ln () . max (0.0) ;
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5 ;
        } else {
            score -= 9.0 + tight * 12.0 ;
        }
        // Late-stream new bins are cheaper than fragmenting
        if step_index > total_items * 4 / 5 {
            score -= 6.0 ;
        }
    }

    // Scarcity coupling
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64 ;
        if slack >= 0.0 && slack < 12.0 {
