    }

    // Mid-stream pairing: prefer bins that can host the next item with a small remainder
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && step_index < total_items * 3 / 5 {
        score -= 1.5 ;
    }

    // NEW: residual-vs-next-item harmony — reward bins whose post-residual is
    // close to the next item's size in relative terms, encouraging chains.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64 ;
        let rel = gap / (next_item_size . max (1) as f64) ;
