    if post_residual > 0 && post_residual < 8 && open_bins_count > 4 {
        score += (8 - post_residual) as f64 * 0.55 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches 0
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 60.0 * tightness * tightness;

    // Dead-space penalty for very small unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item can fit into the post residual
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 18.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit, scaled by how many fit
    if bin_residual == bin_capacity {
        let fit_factor = if fitting_bins_count == 0 { 0.0 } else { 1.0 / fitting_bins_count as f64 };
        score += 15.0 + 30.0 * fit_factor;
        // Early in the stream, opening bins is cheaper; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If mean residual is large, prefer using existing bins
        score += mean_residual * 0.3;
    }

    // Prefer bins whose residual deviates favorably from the mean (use crowded bins)
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.2 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual (tight fits).
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, small residuals are costly (little future use);
    // late in the stream, tight fits matter less, waste matters more.
    let prn = pr / c;
    let coupling = prn * prn * (1.0 - progress) * 40.0 - prn * progress * 25.0;
    score += coupling;

    // Smooth cubic penalty for dead space relative to mean residual state.
    let dead = (prn - (mean_residual / c)).powi(3);
    score += dead * 30.0;

    // Last-chance bonus: strongly favor the only bin that fits (smooth ramp).
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress * 0.3);
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 && next_item_size as f64 <= pr {
        score -= 12.0 * (1.0 - (pr - next_item_size as f64) / c);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 8.0 * ((next_item_size as f64 - pr) / c);
    }

    // Mild penalty for proliferation of open bins (smooth in count).
    score += (open_bins_count as f64).sqrt() * 2.0;

    // New-bin candidate: neutral-ish baseline; only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
