    // Modulo-class preference: residues congruent to 0 mod 10 are more reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Progress-scaled tightness reward
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.1 * (0.5 + 0.5 * progress);

    score
}

