    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item is small and would be wasted on this residual anyway.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size < 10 {
