            score += 8.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when open bins
    // fit poorly (large post_residual everywhere) or bins are scarce.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with the number of open bins.
        let mut new_bin_score = 70.0 + (open_bins_count as f64).sqrt() * 12.0;
        // If many bins can fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            new_bin_score += 35.0 * (fitting_bins_count as f64);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
