pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: dead-space quality ---
    // Class 0: post_residual is "perfect" (0) -> best possible closure.
    // Class 1: post_residual <= 10 -> nearly perfect, tiny dead space.
    // Class 2: post_residual in (10, 25] -> small but reusable gap.
    // Class 3: post_residual in (25, 50] -> half-bin gap, very reusable.
    // Class 4: post_residual > 50 -> large gap, wasteful split.
    let residue_class: u32 = if post_residual == 0 {
        0
    } else if post_residual <= 10 {
        1
    } else if post_residual <= 25 {
        2
    } else if post_residual <= 50 {
        3
    } else {
        4
    };

    // Reward good classes, penalize bad ones (scaled by capacity fraction).
    let cap_frac = (bin_capacity as f64).recip(); // 0.01
    match residue_class {
        0 => score -= 40.0,
        1 => score -= 22.0,
        2 => score -= 8.0,
        3 => score -= 2.0,
        _ => score += 12.0 * (post_residual as f64) * cap_frac * 4.0,
    }

    // --- Integer-division harmony: does post_residual divide nicely with
    // typical small item sizes? Residuals that are multiples of 5 or 10
    // are more likely to be exactly filled by future items. ---
    let harmonic = post_residual % 10 == 0 || post_residual % 5 == 0;
    if harmonic && post_residual > 0 {
        score -= 6.0;
    }
    // Odd primes-ish residuals are awkward.
    if post_residual % 2 == 1 && post_residual > 3 {
        score += 2.5;
    }

    // --- Lookahead coupling via integer division thresholds ---
    if next_item_size > 0 {
        // next_item_size quantized into coarse classes: tiny/small/mid/large
        let next_class = next_item_size / 20; // 0..=5 (0..19,20..39,40..59,...)
        // Does the post-residual exactly host the next item?
        if post_residual == next_item_size {
            score -= 30.0; // perfect two-step chain
        } else if post_residual >= next_item_size {
            // Next item fits comfortably; bonus scales with how tight it is.
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 18.0;
            } else if slack <= 25 {
                score -= 10.0;
            } else {
                score -= 3.0;
            }
        } else {
            // Next item will NOT fit here -> dead space for the lookahead.
            let waste_ratio = (next_item_size - post_residual) as f64 / (bin_capacity as f64);
            score += 14.0 * waste_ratio * 10.0;
            // But if residual is tiny, it's just a closed bin, fine.
            if post_residual <= 10 {
                score += 8.0; // soften: closure beats stranded gap
            }
        }
        // Harmonic check: residual is a multiple of the next item's decade class
        if next_class > 0 && post_residual % (next_class * 10) == 0 && post_residual > 0 {
            score -= 4.0;
        }
    } else {
        // Last item: prefer exact closure aggressively.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only this bin can host the item; opening a new bin wastes the residual.
        // Reward using it proportionally to how much residual would be stranded.
        score -= 10.0 + 0.25 * (bin_residual - item_size) as f64;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // A fresh bin starts with full capacity; its post_residual == capacity - item.
        // Penalize opening a new bin unless the item is large (good long-term use)
        // or stream is early (plenty of future items to fill it).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 18.0 * item_frac - 10.0 * (1.0 - progress);
        // If item leaves a harmonic residual in the new bin, soften penalty.
        let new_post = bin_capacity - item_size;
        if new_post % 10 == 0 {
            score -= 5.0;
        }
    }

    // --- Congestion modulation ---
    // Many open bins with high mean residual -> prefer tightening existing bins
    // (penalize spreading), i.e., favor bins whose post_residual is below mean.
    if open_bins_count > 1 {
        let diff = (post_residual as f64) - mean_residual;
        score += 0.08 * diff; // below-mean residuals get rewarded
    }

    // Mild progress-aware tightening: later in the stream, waste hurts more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

