            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5;
        } else {
            score -= 9.0 + tight * 12.0;
        }
        if step_index > total_items * 4 / 5 {
            score -= 6.0;
        }
        if fitting_bins_count > 2 && next_item_size > 0 && next_item_size <= post_residual.max(next_item_size) {
            score += 5.0;
        }
        // Early-stream bin conservation: don't open new bins for loose fits.
        let remaining_early = total_items.saturating_sub(step_index);
        if remaining_early > 40 && fitting_bins_count >= 1 && tight < 0.35 {
            score += 6.0;
        }
    }

    // Open-bin pressure.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward placements that leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        if post_residual == next_item_size {
            score -= 13.0;
        }
        let slack = post_residual as f64 - next_item_size as f64;
        if fitting_bins_count <= 2 && slack < 12.0 {
            score += 9.0 - slack * 0.6;
        }
        if slack > 0.0 && slack <= 3.0 {
            score -= 2.0;
        }
        if slack > 3.0 && slack <= 7.0 {
            score -= 3.5 - slack * 0.15;
        }
        if slack > 7.0 && slack <= 14.0 && post_residual < 30 {
            score -= (14.0 - slack) * 0.35;
        }
        // Two-item lookahead: chained perfect fits.
        let after = post_residual - next_item_size;
        if after == 0 {
            score -= 6.0;
        } else if after <= 2 {
            score -= 3.0;
        }
        // Slack-band sharpening: exactly-usable remainder for next item.
        if slack > 0.0 && slack <= 2.0 {
            score -= 2.5;
        } else if slack > 2.0 && slack <= 5.0 {
            score -= 1.2;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0;
        } else {
            score += 14.0 + dead_ratio * 9.0;
        }
        // Unusable-slant penalty: tiny leftovers that cannot fit the next item.
        let unusable = post_residual as f64 / next_item_size.max(1) as f64;
        if unusable < 0.35 {
            score += 18.0 * (0.35 - unusable);
        }
    }

    // Mean-residual coupling: prefer tighter bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference to fill older/tighter bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Late-stream small-residual bonuses.
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Residual-fraction fit term — reward near-exact fills, penalize tiny bites.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let frac = (item_size as f64) / (bin_residual as f64);
        if frac >= 0.9 {
            score -= 5.0;
        } else if frac < 0.25 {
            score += (0.25 - frac) * 22.0;
        }
    }

    // Late-stream consolidation — prefer closing bins with near-perfect fills.
    let remaining = total_items.saturating_sub(step_index);
    if remaining <= 12 && post_residual > 0 {
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity.max(1) as f64;
        score -= fill * 4.0;
    }

    // NEW: dead-space budget — penalize bins whose post-fit residual is a
    // large unusable fraction of capacity, pushing toward fuller packing.
    if post_residual > 0 {
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.5 {
            score += (dead_frac - 0.5) * 10.0;
        } else if dead_frac < 0.1 {
            score -= (0.1 - dead_frac) * 12.0;
        }
    }

    // NEW: mean-residual steering — if this bin's residual is far below the
    // fleet mean, it is a consolidation target; reward filling it further.
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual * 0.6 {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below the minimum item size (1..10) are pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Medium-small gaps: moderate penalty scaled by gap size.
        score += 12.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward bins whose residual stays large enough to be reusable.
    if post_residual >= 20 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: this gap likely becomes dead space.
        score += 10.0;
    }

    // Open bins pressure: penalize creating more bins, but relax late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 - 0.3 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins deviating below mean (tighten packed bins).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when open bins are numerous and tight.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead-space minimization, quadratic).
    let util = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * util * util;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportional to wasted lookahead.
            let deficit = (next_item_size - post_residual) as f64;
            score += 10.0 * deficit / bin_capacity as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin would be badly fragmented
    // or the item fits poorly everywhere (few fitting bins, large item).
    if bin_residual == bin_capacity {
        let fragmentation_pressure = if fitting_bins_count > 0 {
            (post_residual as f64) / bin_capacity as f64
                + 5.0 / fitting_bins_count as f64
        } else {
            -50.0
        };
        score += 15.0 + fragmentation_pressure * 30.0;
        // Late in stream, keep bins closed more aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for filling larger residual bins when many are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
