    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * open_pressure;

    // Time horizon: late in the stream, be more conservative — avoid
    // opening new bins and squeeze into existing ones harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * (1.0 - slack_ratio);

