pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = post_norm * (1.0 + 0.9 * post_norm * post_norm);

    // Stream progress coupling: later in stream, penalize wasted space more aggressively
    score += 0.6 * progress * post_norm * post_norm * cap / 100.0;

    // Interaction of post-residual with mean residual: avoid making this bin
    // an outlier far below mean (wasted dead space relative to fleet)
    score += 0.25 * post_norm * (1.0 - (mean_residual / cap).min(1.0));

    // Lookahead coupling: reward leaving room for the next item (smooth term)
    let next_norm = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let fit_gap = post_norm - next_norm;
        score -= 0.35 * (-fit_gap.abs() * 8.0).exp() * (1.0 - fit_gap.abs().min(1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 2 {
        score += 0.15 * (fitting_bins_count as f64 - 2.0);
    }

    // Mild penalty for many open bins to discourage fragmentation
    score += 0.02 * open_bins_count as f64 * post_norm;

    // Perfect fit smoothing
    score -= 1.5 * (-post_norm * 12.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
