pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: gaps divisible by common item sizes are reusable.
    let pr = post_residual;
    if pr > 0 {
        // Perfect fit bonus
        if pr == 0 { score -= 1000.0; }
        // Gap in a "harmonic" residue class (multiples of 5 / 10 are more likely reusable)
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        else { score += 4.0; }

        // Dead-space penalty via integer-division thresholds
        let q = pr / 10; // gap decade class
        if q == 0 { score += 25.0; }          // tiny unusable sliver
        else if q <= 2 { score += 10.0 * (3 - q) as f64; }

        // Lookahead coupling: does the gap fit the next item exactly or at all?
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 40.0; // perfect lookahead fit
            } else if next_item_size <= pr {
                score -= 15.0;
                // harmonic pair: gap leaves a class-aligned remainder for the item after next
                if (pr - next_item_size) % 10 == 0 { score -= 10.0; }
            } else {
                score += 8.0; // gap too small for the known next item
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Waste aversion relative to mean residual of open bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Early stream: prefer tight packing into existing bins; late stream: allow new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / cap);

    // New-bin candidate: neutral baseline, penalized unless it enables a big usable gap
    if bin_residual == bin_capacity {
        score = 60.0 + item_size as f64 * 0.2 - (next_item_size as f64) * 0.1;
        if fitting_bins_count == 0 { score -= 80.0; } // must open new bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
