    // Reward tight fits: fraction of bin used by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Penalize opening a new bin when open bins could fit (new-bin candidate check)
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin is acceptable only if current item would leave a bad gap elsewhere
        // or when bin pressure is low; otherwise discourage.
        let gap_penalty = if post_residual > 0 && post_residual < 10 { 0.0 } else { 40.0 };
        score += gap_penalty;
        // Encourage new bins early when few bins open (distributes load)
        if open_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Open-bins pressure: too many open bins -> prefer filling existing ones
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is a
    // tight bin — using it well is valuable; avoid leaving it worse.
    let residual_gap = bin_residual as f64 - mean_residual;
    score -= residual_gap * 0.1;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 15.0 - next_fit_quality * 0.3;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for next item: mild penalty proportional to waste
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // Stream progression: late in stream, consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
