    }

    // Global compaction term, progress-scaled
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64 ;
        if dev > 0.0 {
            let progress = (step_index as f64) / (total_items . max (1) as f64) ;
            score -= dev * (0.18 + 0.18 * progress) ;
        }
    }

    // Late-stream exact-fill bonus (extended range)
    if post_residual > 0 && post_residual <= 5 && step_index > total_items * 2 / 3 {
        score -= 7.0 ;
    }

    // Early tiny residual penalty
    if post_residual > 0 && post_residual < 6 && step_index <= total_items / 2 {
        score += 3.5 ;
    }

    // Late-stream squeeze
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4 ;
    }

    // Fragmentation guard
    if open_bins_count > 8 && post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 5.0 ;
    }

    // Two-step lookahead: reserve bins whose residual fits the next item exactly
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        score -= 2.5 ;
    }

    // Perfect-fill dominant bonus
    if post_residual > 0 && post_residual <= 2 {
        score -= 4.0 ;
    }

    // Mid-stream pairing
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && step_index < total_items * 3 / 5 {
        score -= 1.5 ;
    }

    // New: triple-fit anticipation — reward bins that fit next item and keep usable remainder
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size >= 8 && post_residual - next_item_size <= 20 {
        score -= 1.0 ;
    }

    // New: penalize creating stranded residuals between 11 and 20 mid-stream
    if post_residual > 10 && post_residual < 20 && step_index < total_items * 3 / 5 && next_item_size > post_residual {
        score += 2.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
