    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 800.0;
        } else if gap <= 15.0 {
            score -= 400.0 - gap * 10.0;
        } else {
            score -= 50.0 / gap;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space,
        // scaled by how much is wasted relative to mean residual.
        let waste = post_residual as f64 - mean_residual;
        score += waste.max(0.0) * 2.0;
    }

    // Penalize leaving residual that no small item could plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // tiny but usable; slight reward
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 150.0;
        // If lookahead shows next item pairs well with a fresh full bin anyway,
        // soften slightly.
        if next_item_size > 0 && item_size + next_item_size as u32 > bin_capacity {
            score -= 100.0;
        }
    }

    // Prefer filling more-opened bins late in the stream (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (open_bins_count as f64).ln().max(1.0) * 0.1;

    // Mild tie-break: prefer bins whose residual deviates favorably from mean.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

