pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is already the base, amplify near-perfect fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never be used by typical items (post_residual too small).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    // Lookahead coupling: bonus if next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot follow here; mild penalty proportional to overflow gap
            score += 2.0 * ((next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Many open bins with high mean residual: encourage consolidation into fuller bins.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score += 0.05 * residual_gap; // prefer bins below-average residual (fuller bins)
    } else {
        score += 0.02 * residual_gap.abs(); // slight penalty for emptier bins when mean is low
    }

    // Time horizon: early in the stream, be more willing to spread items (favor new bins
    // for large items to preserve flexibility); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        // early: slight preference for new bins when item is large
        if bin_residual == bin_capacity {
            score -= 3.0 + 0.05 * item_size as f64;
