        if bin_residual == bin_capacity {
            score += 6.0 + 10.0 * progress;
        }
    }

    // New-bin candidate baseline: must not win unless it is genuinely attractive.
    if bin_residual == bin_capacity && post_residual == bin_capacity {
        score += 1.0;
    }

    // Reward bins whose residual after placement stays "usable" (>= next likely small item).
    if post_residual >= 20 {
        score -= 2.0;
    }

    // Mild penalty proportional to number of open bins to discourage bin proliferation.
    score += 0.01 * open_bins_count as f64;

    score
}

