        } else if frac < 0.25 {
            score += (0.25 - frac) * 22.0;
        }
    }

    // Late-stream consolidation — prefer closing bins with near-perfect fills.
    let remaining = total_items.saturating_sub(step_index);
    if remaining <= 12 && post_residual > 0 {
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity.max(1) as f64;
        score -= fill * 4.0;
    }

    // Slack-band sharpening — reward leaving exactly a small usable remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 2.0 {
            score -= 2.5;
        } else if gap <= 5.0 {
            score -= 1.2;
        }
    }

    // Early-stream bin conservation — avoid opening new bins too eagerly.
    if bin_residual == bin_capacity && remaining > 40 && fitting_bins_count >= 1 {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        if tight < 0.35 {
            score += 6.0;
        }
    }

    // NEW: mid-band dead-space penalty — residuals that are too large to be
    // "tight" but too small for the next item are the worst kind of waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 8.0 {
            score += (8.0 - shortfall) * 1.8; // near-miss: painful but recoverable
        }
    }

    // NEW: horizon-aware exact-fill escalation — the closer to the end of the
    // stream, the more valuable a perfectly closed bin becomes.
    if post_residual == 0 && remaining > 0 {
        let horizon = 1.0 - (remaining.min(60) as f64) / 60.0;
        score -= 60.0 + horizon * 40.0;
    }

    // NEW: multi-fit competition — when several bins can take the item, prefer
    // the one whose post-residual best matches the next item's size class.
    if next_item_size > 0 && fitting_bins_count > 1 && post_residual > 0 {
        let match_err = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            ((next_item_size - post_residual) as f64) * 2.5
        };
        score += match_err * 0.45;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: group dead space into capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward tight fits: post_residual in low harmonic classes (0, small divisors of capacity)
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 30.0;
    } else if post_residual <= 30 {
        score -= 10.0;
    }

    // Modulo arithmetic: post_residual divisible by small harmonics (5,10,20,25) is reusable
    if post_residual % 10 == 0 {
        score -= 15.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 5.0;
    }
    if post_residual % 20 == 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 {
        score -= 8.0;
    }

    // Penalize awkward dead space (odd residues in mid-range)
    if post_residual > 30 && post_residual % 2 == 1 {
        score += 6.0;
    }

    // Lookahead coupling: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap); // tighter next fit is better
        } else {
            // next item cannot follow here; penalize proportionally
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Prefer bins below mean residual (consolidate emptier bins? keep fuller bins tight)
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // New-bin candidate: make it moderately attractive only when item is large relative to capacity
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let load_frac = item_size as f64 / cap;
        // opening a new bin is good for big items, bad for small ones
        score += 30.0 * (1.0 - load_frac);
        if fitting_bins_count > 0 && load_frac < 0.5 {
            score += 80.0; // discourage wasteful new bins for small items
        }
        if load_frac > 0.7 {
            score -= 40.0;
        }
    }

    // Mild stream-progression tiebreak: later in stream, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new {
        score -= 8.0 * progress;
    }

    // Slight preference for fewer open bins when many are open
    score += (open_bins_count as f64) * 0.3;

    score
}

