        if step_index > total_items * 4 / 5 {
            score -= 6.0 ;
        }
    }

    // Scarcity coupling
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64 ;
        if slack >= 0.0 && slack < 12.0 {
            score += 9.0 - slack * 0.6 ;
        }
    }

    // Global compaction term, progress-scaled
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64 ;
        if dev > 0.0 {
            let progress = (step_index as f64) / (total_items . max (1) as f64) ;
            score -= dev * (0.18 + 0.20 * progress) ;
        }
    }

    // Late-stream exact-fill bonus (extended range)
    if post_residual > 0 && post_residual <= 5 && step_index > total_items * 2 / 3 {
        score -= 7.0 ;
    }

    // Early tiny residual penalty
    if post_residual > 0 && post_residual < 6 && step_index <= total_items / 2 {
        score += 3.5 ;
    }

    // Late-stream squeeze
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4 ;
    }

    // Fragmentation guard
    if open_bins_count > 8 && post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 5.0 ;
    }

    // Two-step lookahead: reserve bins whose residual fits the next item exactly
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        score -= 2.5 ;
    }

    // Perfect-fill dominant bonus
    if post_residual > 0 && post_residual <= 2 {
        score -= 4.0 ;
    }

    // Mid-stream pairing
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && step_index < total_items * 3 / 5 {
        score -= 1.5 ;
    }

    // NEW: residual-scale coupling — prefer bins whose post residual is a small
    // fraction of capacity, scaled by progress (compaction pressure)
    if post_residual > 0 && bin_capacity > 0 {
        let pr = (post_residual as f64) / (bin_capacity as f64) ;
        if pr < 0.12 {
            score -= (0.12 - pr) * 30.0 * (1.0 + (step_index as f64) / (total_items . max (1) as f64)) ;
        }
    }

    // NEW: lookahead dead-space reconciliation — when the next item would leave
    // a near-zero remainder after this fit, reward strongly (chain packing)
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size ;
        if rem <= 8 {
            score -= 3.0 - rem as f64 * 0.25 ;
        }
    }

    // NEW: penalize creating residuals that no plausible next item can use
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64 ;
        if gap > 20.0 {
            score += gap * 0.22 ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: gaps too small to be useful are worthless.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score += (11 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        score += (21 - post_residual) as f64 * 2.0;
    }

    // Fit-quality coupling: reward tight fills relative to remaining space.
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual.max(1) as f64);
        score -= ratio * 6.8 + ratio * ratio * 6.2;
    }

    // Waste penalty (non-linear).
    let waste = bin_residual.saturating_sub(item_size);
    if waste > 0 {
        let w = waste as f64;
        score += if w < 6.0 { w * 0.3 } else { w.sqrt() * 1.45 };
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        let crowding = (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5;
        } else {
            score -= 9.0 + tight * 12.0;
        }
        if step_index > total_items * 4 / 5 {
            score -= 6.0;
        }
        if fitting_bins_count > 2 && next_item_size > 0 && next_item_size <= post_residual.max(next_item_size) {
            score += 5.0;
        }
    }

    // Open-bin pressure.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward placements that leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        if post_residual == next_item_size {
            score -= 13.0;
        }
        let slack = post_residual as f64 - next_item_size as f64;
        if fitting_bins_count <= 2 && slack < 12.0 {
            score += 9.0 - slack * 0.6;
        }
        if slack > 0.0 && slack <= 3.0 {
            score -= 2.0;
        }
        if slack > 3.0 && slack <= 7.0 {
            score -= 3.5 - slack * 0.15;
        }
        if slack > 7.0 && slack <= 14.0 && post_residual < 30 {
            score -= (14.0 - slack) * 0.35;
        }
        // Two-item lookahead: chained perfect fits.
        let after = post_residual - next_item_size;
        if after == 0 {
            score -= 6.0;
        } else if after <= 2 {
            score -= 3.0;
        }
        // NEW: triple-chained lookahead — reward residuals that can absorb the
        // next item AND still leave a tiny usable remainder for the one after.
        if after >= 3 && after <= 12 && fitting_bins_count > 1 {
            score += after as f64 * 0.35;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0;
        } else {
            score += 14.0 + dead_ratio * 9.0;
        }
        // Unusable-slant penalty: tiny leftovers that cannot fit the next item.
        let unusable = post_residual as f64 / next_item_size.max(1) as f64;
        if unusable < 0.35 {
            score += 18.0 * (0.35 - unusable);
        }
    }

    // Mean-residual coupling: prefer tighter bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference to fill older/tighter bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Late-stream small-residual bonuses.
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Residual-fraction fit term — reward near-exact fills, penalize tiny bites.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let frac = (item_size as f64) / (bin_residual as f64);
        if frac >= 0.9 {
            score -= 5.0;
        } else if frac < 0.25 {
            score += (0.25 - frac) * 22.0;
        }
    }

    // Late-stream consolidation — prefer closing bins with near-perfect fills.
    let remaining = total_items.saturating_sub(step_index);
    if remaining <= 12 && post_residual > 0 {
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity.max(1) as f64;
        score -= fill * 4.0;
    }

    // Slack-band sharpening — reward leaving exactly a small usable remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 2.0 {
            score -= 2.5;
        } else if gap <= 5.0 {
            score -= 1.2;
        }
    }

    // Early-stream bin conservation — avoid opening new bins too eagerly.
    if bin_residual == bin_capacity && remaining > 40 && fitting_bins_count >= 1 {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        if tight < 0.35 {
            score += 6.0;
        }
    }

    // Mid-band dead-space penalty — residuals too large to be tight but too
    // small for the next item are the worst kind of waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 8.0 {
            score += (8.0 - shortfall) * 1.8;
        }
    }

    // Horizon-aware exact-fill escalation.
    if post_residual == 0 && remaining > 0 {
        let horizon = 1.0 - (remaining.min(60) as f64) / 60.0;
        score -= 60.0 + horizon * 40.0;
    }

    // Multi-fit competition — prefer post-residual matching next item's size class.
    if next_item_size > 0 && fitting_bins_count > 1 && post_residual > 0 {
        let match_err = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            ((next_item_size - post_residual) as f64) * 2.5
        };
        score += match_err * 0.45;
    }

    // NEW: dead-space ratio sharpening — when several bins fit, penalize bins
    // whose post-residual will almost certainly become stranded dead space by
    // comparing post_residual against the global mean residual.
    if post_residual > 0 && fitting_bins_count > 1 {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.4 && pr < 15.0 {
            score += (15.0 - pr) * 0.9;
        } else if pr >= mean_residual * 0.9 {
            score -= 2.0;
        }
    }

    // NEW: mid-stream tightness escalation — in the middle of the stream,
    // strongly prefer near-exact residual consumption to keep bins dense.
    if remaining > 40 && remaining < total_items.saturating_sub(40) {
        let fill_frac = (bin_residual.saturating_sub(item_size)) as f64 / bin_capacity.max(1) as f64;
        if fill_frac < 0.08 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer low post-residual (tight fit), scaled by capacity.
    let mut score = pr;

    // Non-linear coupling: quadratic penalty on post-residual, modulated by stream progress.
    // Early in the stream, moderate residuals are acceptable; late, they are costly.
    let q = (pr / cap) * (pr / cap);
    score += 40.0 * q * (0.5 + progress);

    // Cubic dead-space term: strongly punish residuals too small to be useful later.
    let small = (pr / cap).powi(3);
    score += 60.0 * small;

    // Interaction: item size vs residual — large items into tight bins is good (tight fit reward).
    let item_f = item_size as f64;
    let fit_ratio = item_f / cap;
    score -= 25.0 * fit_ratio * (1.0 - pr / cap);

    // Mean residual coupling: prefer bins whose residual deviates favorably from the mean.
    score += 0.5 * (pr - mean_residual) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.5 + progress);
    }

    // Lookahead: if next item fits into post_residual, reward leaving that much space.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Penalize opening new bins when many bins are already open and progress is high.
    let new_bin_bias = if bin_residual == bin_capacity {
        20.0 + 40.0 * progress + 2.0 * open_bins_count as f64
    } else {
        0.0
    };
    score += new_bin_bias;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;

    // Dead-space penalty for the lookahead item (refined tiers)
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size . max (1) as f64 ;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0 ;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0 ;
        } else {
            score += 14.0 + dead_ratio * 9.0 ;
        }
