    // Best-fit pressure with non-linear fill term (combined from best + parent)
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual . max (1) as f64) ;
        score -= ratio * 7.0 + ratio * ratio * 6.8 ;
    }

    // Waste penalty with mild convexity
    let waste = bin_residual . saturating_sub (item_size) ;
    if waste > 0 {
        let w = waste as f64 ;
        score += if w < 6.0 { w * 0.3 } else { w . sqrt () * 1.45 } ;
    }

    // Exact-fill lookahead bonus (strengthened)
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0 ;
    }
    // Near-miss lookahead
    if post_residual > next_item_size && post_residual <= next_item_size + 7 && next_item_size > 0 {
        score -= 3.5 - (post_residual - next_item_size) as f64 * 0.15 ;
    }
    // Chain lookahead
    if post_residual > next_item_size && next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
        score -= 4.0 ;
    }

    // New-bin arbitration with crowding pressure
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity . max (1) as f64) ;
        let crowding = (open_bins_count as f64) . ln () . max (0.0) ;
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5 ;
        } else {
            score -= 9.0 + tight * 12.0 ;
        }
        // Late-stream new bins are cheaper than fragmenting
        if step_index > total_items * 4 / 5 {
            score -= 6.0 ;
        }
    }

    // Scarcity coupling
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64 ;
        if slack >= 0.0 && slack < 12.0 {
            score += 9.0 - slack * 0.6 ;
        }
    }

    // Global compaction term, progress-scaled (stronger toward end)
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64 ;
        if dev > 0.0 {
            let progress = (step_index as f64) / (total_items . max (1) as f64) ;
            score -= dev * (0.18 + 0.24 * progress) ;
        }
    }

    // Late-stream exact-fill bonus (extended range)
    if post_residual > 0 && post_residual <= 5 && step_index > total_items * 2 / 3 {
        score -= 7.0 ;
    }

    // Early tiny residual penalty
    if post_residual > 0 && post_residual < 6 && step_index <= total_items / 2 {
        score += 3.5 ;
    }

    // Late-stream squeeze: prefer near-full bins when nearing the end
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4 ;
    }

    // Fragmentation guard
    if open_bins_count > 8 && post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 5.0 ;
    }

    // Two-step lookahead: reserve bins whose residual fits the next item exactly
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        score -= 3.0 ;
    }

    // Perfect-fill dominant bonus
    if post_residual > 0 && post_residual <= 2 {
        score -= 4.5 ;
    }

    // Mid-stream pairing
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && step_index < total_items * 3 / 5 {
        score -= 1.8 ;
    }

    // New lookahead: two-item chain fit — bin can host next item then a tiny remainder
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size > 0 {
        let after_next = post_residual - next_item_size ;
        if after_next <= 4 && step_index > total_items / 3 {
            score -= 2.0 + (4 - after_next) as f64 * 0.5 ;
        }
    }

    // Dead-space avoidance coupling with mean residual: bins well below mean residual late are penalized
    if bin_residual < bin_capacity && post_residual > 0 && post_residual < 14 && step_index > total_items / 2 {
        score += 2.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Class 0: perfectly divisible into quarters -> highly reusable leftovers.
    // Class 1: leaves a remainder of 1..=4 -> nearly dead space, penalize.
    // Class 2: divisible by 5 or 10 -> medium reusability.
    let residue_class = post_residual % 4;
    match residue_class {
        0 => score -= 6.0,
        1 => score += 8.0,
        2 => score -= 2.0,
        _ => score += 3.0,
    }

    // Integer-division thresholds on post_residual: buckets of usable space.
    let bucket = post_residual / 10;
    score -= (bucket as f64) * 1.5;

    // Penalize tiny dead space (post_residual in 1..=5) strongly: wasted capacity.
    if post_residual > 0 && post_residual <= 5 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a perfect chain -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits but not perfectly: reward proportionally.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack * 0.3;
        } else {
            // Next item won't fit here: slight penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.15;
        }
        // Harmonic class of next item vs post residual: if post_residual % next_item_size == 0,
        // multiple future items could stack here.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has large raw post_residual already;
    // dampen its natural advantage unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0; // discourage opening a new bin when an open bin chains well
        }
    }

    // Fraction-of-capacity coupling: reward filling large fractions of the bin now.
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= fill_fraction * 8.0;

    // Stream progression: early on, be more willing to open bins (keep options open);
    // late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 6.0;
    } else {
        score += (1.0 - progress) * 2.0;
    }

    // Mean residual coupling: if this bin is far below the mean residual, it is a
    // "ragged" bin; prefer packing it to normalize residuals.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.4;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 {
        // A gap is "dead" if the lookahead item cannot use it either.
        let gap_dead = next_item_size > 0 && post_residual < next_item_size;
        if gap_dead {
            score += 40.0 + 0.5 * post_residual as f64;
        }
        // Perfect fit gets strong reward.
        if post_residual == 0 {
            score -= 25.0;
        } else if post_residual <= 5 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item leaves a large,
    // reusable residual elsewhere or fits nowhere well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin is penalized more as open bins pile up.
        score += 15.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
        // But if mean residual is high (open bins are fragmented), a fresh bin is fine.
        score -= (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // Slight preference for bins below mean residual (consolidate emptier space).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Lookahead synergy: reward if post_residual matches next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance with dead-ratio scaling toward the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        if post_residual < 22 {
