        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0;
        } else {
            score += 14.0 + dead_ratio * 9.0;
        }
    } else if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward gaps that can still host a typical future item.
    if post_residual >= 40 {
        score -= 8.0;
    }

    // Lookahead: exact match strongly favored; near-exact mildly favored.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 7.0 {
            score -= 10.0 - slack * 0.9;
        } else {
            score -= 6.0;
        }
    }

    // Fill-ratio coupling: prefer bins where the item tightly fills the residual.
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual.max(1) as f64);
        score -= ratio * 6.8 + ratio * ratio * 6.2;
    }

    // Waste shaping on the current bin.
    let waste = bin_residual.saturating_sub(item_size);
    if waste > 0 {
        let w = waste as f64;
        score += if w < 6.0 { w * 0.3 } else { w.sqrt() * 1.45 };
    }

    // Last-chance pressure: only fitting bin, avoid opening new bins.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // New-bin candidate logic: open a new bin only for large items or when
    // existing bins would create dead space.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        let crowding = (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5;
        } else {
            score -= 9.0 + tight * 12.0;
        }
        if step_index > total_items * 4 / 5 {
            score -= 6.0;
        }
    } else {
        score += open_bins_count as f64 * 0.5;
    }

    // Borrowed from best: tight-fit penalty when few fitting bins and slack small.
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack >= 0.0 && slack < 12.0 {
            score += 9.0 - slack * 0.6;
        }
    }

    // Late-stream tightening: small residuals become less valuable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 25 {
        score += 10.0 * progress;
    }
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Micro-slack lookahead bonus: near-exact next-item fits within 3 units.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        score -= 2.0;
    }

    // Mean-residual coupling: when open bins are collectively roomy, discourage
    // dumping into an already-large gap that would exceed the mean residual.
    if post_residual > 0 && mean_residual > 0.0 && (post_residual as f64) > mean_residual * 1.6 {
        score += 3.0;
    }

    // NEW: two-step lookahead chain — reward residuals that can host both the
    // next item and leave room for a plausible follow-up item.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 40 {
            score -= 3.0;
        } else if after >= 20 && next_item_size >= after {
            score -= 2.0;
        }
    }

    // NEW: pair-fit shaping — when the current item plus next item exactly or
    // nearly exactly fills the bin residual, strongly prefer this bin.
    if post_residual > 0 && next_item_size > 0 {
        let pair = item_size.saturating_add(next_item_size);
        if pair == bin_residual {
            score -= 26.0;
        } else if bin_residual >= pair && bin_residual - pair <= 5 {
            score -= 9.0 - (bin_residual - pair) as f64 * 1.2;
        }
    }

    // NEW: fragment-risk penalty — avoid leaving residuals that are just below
    // a mid-sized item band (hard-to-fill dead zones).
    if post_residual > 0 && post_residual < 40 {
        let r = post_residual as f64;
        if r > 10.0 && r < 18.0 {
            score += 4.5 - (r - 10.0) * 0.35;
        }
    }

    // NEW: mean-residual anchoring — prefer bins whose resulting residual is
    // close to the open-bin mean, keeping future flexibility uniform.
    if post_residual > 0 && mean_residual > 0.0 {
        let dev = ((post_residual as f64) - mean_residual).abs();
        if dev < 8.0 {
            score -= 2.5 - dev * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.6 * tightness * (bin_capacity as f64);

    // 2-step lookahead: strongly reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect 2-item fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot fit here: penalize leftover dead space
            let dead = (post_residual as f64) / (bin_capacity as f64);
            score += 25.0 * dead;
        }
    } else {
        // last item: just minimize post_residual
        score += 0.1 * post_residual as f64;
    }

    // Compare against mean residual: bins with residual far from mean get normalized.
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Slight preference for reusing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress; // penalize opening new bins
    }

    // Encourage consolidation when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but avoid exact-zero
    // dead-space chasing when the next item could use the leftover.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; leftover becomes dead space unless small.
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 0.35 * waste;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        // Many options: be pickier about loose fits.
        score += 0.15 * post_residual as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity (would leave open bins cramped anyway)
    // or all open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        let avg_full = 1.0 - mean_residual / bin_capacity as f64;
        // Penalize new bins early / when open bins are loose; discount when
        // item is big and mean residual is small.
        let item_share = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - progress) * (1.0 - item_share)
                 + 10.0 * (1.0 - avg_full)
                 - 15.0 * item_share * (1.0 - mean_residual / bin_capacity as f64)
                 - 2.0 * openness.min(6.0) * (mean_residual / bin_capacity as f64);
        // Never let a fresh bin look too attractive.
        score = score.max(8.0);
    }

    // Mild global pressure: when many bins are open and mean residual is small,
    // encourage packing into existing space.
    let mr = mean_residual / bin_capacity as f64;
    score += 3.0 * (1.0 - mr) - 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;

    // Dead-space penalty for the lookahead item (refined tiers)
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size . max (1) as f64 ;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0 ;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0 ;
        } else {
            score += 14.0 + dead_ratio * 9.0 ;
        }
    }

    // Best-fit pressure with non-linear fill term (combined calibration)
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual . max (1) as f64) ;
        score -= ratio * 7.1 + ratio * ratio * 6.8 ;
    }

    // Waste penalty with mild convexity
    let waste = bin_residual . saturating_sub (item_size) ;
    if waste > 0 {
        let w = waste as f64 ;
        score += if w < 6.0 { w * 0.3 } else { w . sqrt () * 1.45 } ;
    }

    // Exact-fill lookahead bonus
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 13.5 ;
    }
    // Near-miss lookahead
    if post_residual > next_item_size && post_residual <= next_item_size + 7 && next_item_size > 0 {
        score -= 3.5 - (post_residual - next_item_size) as f64 * 0.15 ;
    }
    // Chain lookahead
    if post_residual > next_item_size && next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
        score -= 4.0 ;
    }

    // New-bin arbitration with crowding pressure
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity . max (1) as f64) ;
        let crowding = (open_bins_count as f64) . ln () . max (0.0) ;
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5 ;
        } else {
            score -= 9.0 + tight * 12.0 ;
        }
        if step_index > total_items * 4 / 5 {
            score -= 6.0 ;
        }
    }

    // Scarcity coupling
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64 ;
        if slack >= 0.0 && slack < 12.0 {
            score += 9.0 - slack * 0.6 ;
        }
    }

    // Global compaction term, progress-scaled
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64 ;
        if dev > 0.0 {
            let progress = (step_index as f64) / (total_items . max (1) as f64) ;
            score -= dev * (0.18 + 0.18 * progress) ;
        }
    }

    // Late-stream exact-fill bonus (extended range)
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0 ;
    }

    // Early tiny residual penalty
    if post_residual > 0 && post_residual < 6 && step_index <= total_items / 2 {
        score += 3.5 ;
    }

    // Late-stream squeeze
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4 ;
    }

    // Fragmentation guard
    if open_bins_count > 8 && post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 5.0 ;
    }

    // Two-step lookahead: reserve bins whose residual fits the next item exactly
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        score -= 2.2 ;
    }

    // Perfect-fill dominant bonus
    if post_residual > 0 && post_residual <= 2 {
        score -= 4.0 ;
    }

    // Mid-stream pairing: prefer bins that can host the next item with a small remainder
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && step_index < total_items * 3 / 5 {
        score -= 1.5 ;
    }

    // New coupling: when many bins fit, reward tighter residuals harder to force compaction
    if fitting_bins_count >= 3 && post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity . max (1) as f64) ;
        score -= tightness * 2.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Smooth polynomial coupling: residual penalized more as stream progresses
    let progress_weight = progress * progress * (3.0 - 2.0 * progress);
    score += 12.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress_weight);
    // Reward tight fits via smooth interaction of item size and residual
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    score -= 8.0 * tightness * tightness * (1.0 + progress_weight);
    // Penalize when post residual is unusable for the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 6.0 * gap * gap;
    }
    // Last-chance bonus when this bin is the only fitting one
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - progress);
    }
    // Mild penalty for scattering across many open bins relative to mean residual
    score += 0.5 * ((open_bins_count as f64).ln() + 1.0) * (norm_pr - mean_residual / cap).abs();
    // New-bin candidate: penalize slightly unless residuals are all tight
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress * (1.0 - (mean_residual / cap).powi(2));
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.93;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 8 harmonic bands.
    // Residuals in low bands (tight fit) are valuable -> reward (subtract).
    let band = (post_residual * 8 / bin_capacity.max(1)) as f64;
    score -= (8.0 - band) * 6.0;

    // Modular class logic on post_residual mod 10: residuals divisible by 10
    // are more reusable by integer-sized items -> reward them.
    let m10 = post_residual % 10;
    score += m10 as f64 * 1.5;

    // Perfect fit: zero dead space is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tiny dead space (1..=5) is nearly unusable -> penalize hard.
    if post_residual > 0 && post_residual <= 5 {
        score += 120.0;
    }

    // Harmonic pairing: does post_residual exactly fit next_item_size?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0; // sets up a perfect fit next step
        } else if post_residual >= next_item_size {
            let ratio = next_item_size as f64 / post_residual as f64;
            // Reward high fill ratio of residual by next item
            score -= ratio * 40.0;
            // Integer-division threshold: how many times next item fits in residual
            let k = post_residual / next_item_size.max(1);
            score -= k as f64 * 8.0;
        } else {
            // Next item cannot use this residual: dead space likely persists
            score += 30.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    // or no good fit exists (large post_residual elsewhere would waste space).
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        // Base penalty so new bins are used only when justified.
        score += 60.0;
        // Large items deserve fresh bins.
        if fill > 0.5 {
            score -= fill * 70.0;
        }
        // Late in the stream with many bins open, prefer consolidating.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 25.0 + open_bins_count as f64 * 2.0;
    }

    // Coupling with mean residual: prefer bins far below mean residual
    // (consumes the outliers, keeps many mid-size residuals).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to hold the smallest plausible item are wasted.
    let min_gap = 10u32;
    if post_residual > 0 && post_residual < min_gap {
        score += 60.0; // tiny unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit, zero waste
    } else if post_residual < 20 {
        score += 10.0; // likely-dead small gap
    }

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += 8.0 * fit_ratio;

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and mean residual available elsewhere.
        score += 15.0 + pressure * 3.0 + mean_residual * 0.3;
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 12.0;
        }
    } else {
        // Placing in an open bin reduces fragmentation pressure slightly.
        score -= pressure * 0.5;
        // If next item fits in the post residual, reward this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Penalize leaving a gap that just barely fails to fit the next item (bad sequencing).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Aggressive 2-step lookahead: if next item exactly fits the post_residual,
    // strongly reward this placement (perfect 2-chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits too: reward proportionally to how snugly it will fit.
            let next_leftover = post_residual - next_item_size;
            score -= 30.0 * (1.0 - next_leftover as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space more when
            // the gap is small-but-unusable (worst kind of dead space).
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 25.0;
            } else {
                score += (gap as f64).min(30.0) * 0.5;
            }
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 20.0 * (1.0 - tightness);
    }

    // Relative to mean residual: prefer bins that are already more filled
    // than average (best-fit tendency), avoid spreading waste evenly.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    // Penalize opening a new bin unless the item is large and current open
    // bins would leave very awkward leftovers.
    if bin_residual == bin_capacity {
        // Baseline penalty for opening a new bin.
        score += 30.0;
        // But if item is large (>50), a fresh bin may be better than fragmenting.
        if item_size > 50 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If no open bins at all, must open.
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Small coupling: many open bins -> prefer consolidating into existing ones.
    if open_bins_count > 3 {
        score += 0.5 * open_bins_count as f64 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (waste grows quadratically as dead space).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 {
        // Penalize leaving residue that the next item cannot use.
        score += (post_residual as f64) * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 30.0 - 10.0 * progress;
        // If many bins are open with slack, discourage opening yet another.
        open_cost += (open_bins_count as f64) * 1.5;
        // If mean residual is small, fits are tight -> opening a bin is more acceptable.
        open_cost -= mean_residual * 0.3;
        score += open_cost.max(5.0);
    } else {
        // Slight preference for fuller bins relative to the mean residual.
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    // Early stream: be a bit conservative with tight fits to keep flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score += (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: post_residual weighted by stream progress
    let poly = norm_pr * (1.0 + 2.0 * progress * norm_pr + progress * progress * norm_pr * norm_pr);
    score += poly * cap * 0.5;

    // Penalize large post_residual relative to mean residual (dead space creation)
    score += (pr - mean_residual) * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) with smooth quadratic term
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 8.0 * (1.0 - progress);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    }

    // Slight preference to keep number of open bins low early on
    score += open_bins_count as f64 * (1.0 - progress) * 0.4;

    // New-bin candidate: penalize opening a new bin unless residual is very tight
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;

    // Dead-space penalty for the lookahead item (refined tiers)
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size . max (1) as f64 ;
        if post_residual < 22 {
