        score += 4.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity-fraction bands.
    // Items 1..100, capacity 100. Small post_residual = tight fit = good.
    let pr = post_residual;
    let class: f64 = match pr {
        0 => -60.0,                      // perfect closure
        1..=5 => -40.0,                  // near-perfect
        6..=10 => -25.0,                 // excellent
        11..=20 => -12.0,                // good
        21..=35 => 0.0,                  // neutral
        36..=50 => 8.0,                  // mediocre dead space
        _ => 15.0,                       // large waste
    };
    score += class;

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes are more reusable (harmonic alignment).
    let harmonics: u32 = [10, 20, 25, 50]
        .iter()
        .filter(|&&d| d > 0 && pr % d == 0 && pr > 0)
        .count() as u32;
    score -= 4.0 * harmonics as f64;

    // Lookahead coupling: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Bonus scaled by how well the next item harmonizes with the residual.
            let next_class = (next_item_size / 10).max(1);
            let pr_class = (pr / 10).max(1);
            let alignment = 1.0 - ((next_class as i32 - pr_class as i32).abs() as f64 / 10.0);
            score -= 10.0 * alignment;
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tightest fits (post_residual already does this).
        score += (fitting_bins_count.min(10) as f64) * 0.5;
    }

    // New-bin candidate handling: an empty bin has huge residual; discourage
    // opening it unless the item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * large_item;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host item + next item
        }
    }

    // Mean-residual pressure: when open bins are generally full, opening a new
    // bin is cheaper; when residuals are plentiful, reuse is preferred.
    let mean_ratio = mean_residual / bin_capacity as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - mean_ratio);
    }

    // Stream progression: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Integer-division threshold on item_size: big items (>50) prefer tight bins.
    if item_size / 10 >= 5 {
        score -= 3.0;
    }

    score
}

