    // Mild diversity pressure: prefer bins deviating from mean residual.
    score += 0.05 * (mean_residual - pr).abs();

    // New-bin candidate: penalize slightly unless current residual is unusable.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress - 12.0 * (1.0 - (item_size as f64 / cap)).exp();
    }

    score
}

