        if fitting_bins_count <= 2 && slack < 12.0 {
            score += 9.0 - slack * 0.6;
        }
        if slack > 0.0 && slack <= 3.0 {
            score -= 2.0;
        }
        if slack > 3.0 && slack <= 7.0 {
            score -= 3.5 - slack * 0.15;
        }
        if slack > 7.0 && slack <= 14.0 && post_residual < 30 {
            score -= (14.0 - slack) * 0.35;
        }
        // Two-item lookahead: chained perfect fits.
        let after = post_residual - next_item_size;
        if after == 0 {
            score -= 6.0;
        } else if after <= 2 {
            score -= 3.0;
        }
        // Triple-chained lookahead — reward residuals that can absorb the
        // next item AND still leave a tiny usable remainder for the one after.
        if after >= 3 && after <= 12 && fitting_bins_count > 1 {
            score += after as f64 * 0.35;
        }
        // NEW: deep-chain anticipation — if the leftover after the next item
        // also matches the next item's size class (small leftovers), reward
        // compaction chains explicitly scaled by stream progress.
        if after >= 1 && after <= 6 {
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= (6 - after) as f64 * (1.5 + progress * 2.0);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0;
        } else {
            score += 14.0 + dead_ratio * 9.0;
        }
        // Unusable-slant penalty: tiny leftovers that cannot fit the next item.
        let unusable = post_residual as f64 / next_item_size.max(1) as f64;
        if unusable < 0.35 {
            score += 18.0 * (0.35 - unusable);
        }
    }

    // Mean-residual coupling: prefer tighter bins (sharpened).
    score += (bin_residual as f64 - mean_residual) * 0.45;

    // Slight preference to fill older/tighter bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Late-stream small-residual bonuses.
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Residual-fraction fit term — reward near-exact fills, penalize tiny bites.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let frac = (item_size as f64) / (bin_residual as f64);
        if frac >= 0.9 {
            score -= 5.0;
        } else if frac < 0.25 {
            score += (0.25 - frac) * 22.0;
        }
    }

    // Late-stream consolidation — prefer closing bins with near-perfect fills.
    let remaining = total_items.saturating_sub(step_index);
    if remaining <= 12 && post_residual > 0 {
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity.max(1) as f64;
        score -= fill * 4.0;
    }

    // Slack-band sharpening — reward leaving exactly a small usable remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 2.0 {
            score -= 2.5;
        } else if gap <= 5.0 {
            score -= 1.2;
        }
    }

    // Early-stream bin conservation — avoid opening new bins too eagerly.
    if bin_residual == bin_capacity && remaining > 40 && fitting_bins_count >= 1 {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        if tight < 0.35 {
            score += 6.0;
        }
    }

    // Mid-band dead-space penalty — residuals too large to be tight but too
    // small for the next item are the worst kind of waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 8.0 {
            score += (8.0 - shortfall) * 1.8;
        }
    }

    // Horizon-aware exact-fill escalation.
    if post_residual == 0 && remaining > 0 {
        let horizon = 1.0 - (remaining.min(60) as f64) / 60.0;
        score -= 60.0 + horizon * 40.0;
    }

    // Multi-fit competition — prefer post-residual matching next item's size class.
    if next_item_size > 0 && fitting_bins_count > 1 && post_residual > 0 {
        let match_err = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            ((next_item_size - post_residual) as f64) * 2.5
        };
        score += match_err * 0.45;
    }

    // Dead-space ratio sharpening — penalize bins whose post-residual will
    // almost certainly become stranded dead space.
    if post_residual > 0 && fitting_bins_count > 1 {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.4 && pr < 15.0 {
            score += (15.0 - pr) * 0.9;
        } else if pr >= mean_residual * 0.9 {
            score -= 2.0;
        }
    }

    // Mid-stream tightness escalation — strongly prefer near-exact residual
    // consumption to keep bins dense.
    if remaining > 40 && remaining < total_items.saturating_sub(40) {
        let fill_frac = (bin_residual.saturating_sub(item_size)) as f64 / bin_capacity.max(1) as f64;
        if fill_frac < 0.08 {
            score -= 3.0;
        }
    }

    // NEW: combined compaction coupling — merge residual-fitting with
    // lookahead: when multiple bins fit, strongly favor the one whose
    // post-residual is simultaneously small AND able to host the next item.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let coupling = (pr - n) / (n.max(1.0));
        if coupling <= 0.5 {
            score -= (0.5 - coupling) * 10.0;
        }
        // Extra reward when this bin's post-residual is the smallest usable
        // among plausible candidates (approximated via mean residual).
        if pr <= mean_residual {
            score -= 3.0;
        }
    }

    // NEW: new-bin gate refinement — when few bins fit and the item is large,
    // resist opening a fresh bin even harder to conserve bin count.
    if bin_residual == bin_capacity && fitting_bins_count == 1 {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        if tight >= 0.6 {
            score += 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly prefer bins where the item exactly fills the residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward if the NEXT item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0; // chain perfect fit
        } else if post_residual > next_item_size {
            // next item fits, reward by tightness of the two-step chain
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 300.0 - chain_waste.min(300.0);
        } else {
            // next item does NOT fit here: penalize wasted lookahead potential
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(200.0);
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than the average open bin.
    let resid = post_residual as f64;
    let dev = resid - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are very full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fullness = 1.0 - (mean_residual / bin_capacity as f64);
        // Only open a new bin if existing bins are well packed or stream is early
        if avg_fullness < 0.6 && progress > 0.1 {
            score += 250.0;
        } else {
            score += 60.0;
        }
    }

    // Penalize creating large dead space that no plausible item (1..100) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 80.0; // tiny unusable slivers are dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty scaled by how badly the residual fails to host the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
