    } else if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Near-exact lookahead fit.
    if post_residual > next_item_size && post_residual <= next_item_size + 7 && next_item_size > 0 {
        score -= 3.5 - (post_residual - next_item_size) as f64 * 0.15;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        let crowding = (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5;
        } else {
            score -= 9.0 + tight * 12.0;
        }
        if step_index > total_items * 4 / 5 {
            score -= 6.0;
        }
    } else {
        score += open_bins_count as f64 * 0.5;
