    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - next_fit / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Post residual too small for the lookahead item: penalize dead space creation.
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
