        if cls == 0 {
            score -= 12.0;
        } else {
            // Penalize awkward classes; class 9 (residual 1..9 dead space) worst.
            score += cls as f64 * 0.8;
        }
        // Dead-space threshold: leftover too small for the smallest plausible item.
        if pr < 10 {
            score += 30.0;
        }
    } else {
        // Perfect fill: best possible outcome.
        score -= 40.0;
    }

    // Integer-division thresholds on post_residual: can it host next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Room for the lookahead item: reward proportional to fit quality.
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 + slack * 0.05;
            // Harmonic pairing: post_residual exactly matches next item -> chain fill.
            if pr == next_item_size {
                score -= 15.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Capacity-fraction coupling: item size relative to capacity.
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.5 {
        // Large items: prefer tightest bins (post_residual already dominates).
        score -= 5.0 * frac;
    } else {
        // Small items: avoid wasting them on near-empty bins.
        score += (1.0 - frac) * 4.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a bin; cheaper later in the stream when
        // many open bins already carry fragmented residual.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score = score.max(0.0) + 25.0 + openness * 5.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // Pairing big-then-small into a fresh bin is efficient.
            score -= 6.0;
        }
    } else {
        // Prefer bins tighter than the mean residual (fragmented bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
