    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits, slight penalty for wasting the pairing opportunity.
    if next_item_size > 0 && post_residual as u32 > 0 && (post_residual as u32) < next_item_size && next_item_size - post_residual as u32 <= 5 {
        score += 8.0;
    }

    // Time horizon: early in the stream, be conservative (favor new bins less),
    // late in the stream, pack aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> discourage spreading,
    // prefer filling bins below the mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or existing bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let size_pressure = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 20.0 * crowding * size_pressure;
    }

    // Mild preference for bins with moderate residual (avoid fragmenting large residuals).
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
