    // is small relative to the global mean, scaled by remaining stream length.
    if post_residual > 0 && remaining > 30 {
        let pr = post_residual as f64;
        let tightness = pr / bin_capacity.max(1) as f64;
        if tightness < 0.12 {
            score -= (0.12 - tightness) * 30.0;
        }
    }

    // NEW: dual-item horizon anticipation — if the next item exactly exhausts the
    // post-residual, prefer leaving a residual that also fits a small follow-up,
    // coupling fine-grained residual fitting with lookahead anticipation.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 6 {
            // Small remainder after next item: mildly penalize unless it can
            // absorb a typical small item (guarded by mean residual).
            let typical = mean_residual.max(6.0);
            if (after as f64) < typical * 0.35 {
                score += 2.2 - after as f64 * 0.25;
            }
        } else if after == 7 || after == 8 {
            score -= 1.5;
        }
    }

    // NEW: residual-band matching — reward bins whose post-residual falls in a
    // dense "reusable" band (10..=30) that historically absorbs mid-size items.
    if post_residual >= 10 && post_residual <= 30 && fitting_bins_count > 1 {
        let band_center = 20.0;
        let dist = ((post_residual as f64) - band_center).abs();
        score -= (10.0 - dist) * 0.22;
    }

    // NEW: crowding-aware consolidation — when many bins are open, escalate the
    // preference for bins that become nearly full, to force bin count reduction.
    if open_bins_count > 8 && post_residual > 0 {
        let fill_now = (bin_capacity - post_residual) as f64 / bin_capacity.max(1) as f64;
        if fill_now > 0.85 {
            score -= (fill_now - 0.85) * 18.0 * ((open_bins_count.min(20)) as f64 / 10.0);
        }
    }

    // NEW: early-stream exact-fit preference to seed compact bins.
    if remaining > total_items * 3 / 4 && item_size == bin_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit = item_size as f64 / cap;
    let tightness = 1.0 - pr / cap;

    // Core: reward tight fits via smooth polynomial in post_residual
    let mut score = pr * (1.0 + 0.8 * tightness * tightness);

    // Smooth coupling of fit quality with stream progress
    score -= 30.0 * fit * fit * (0.5 + 0.5 * progress);

    // Penalize large dead space more as stream progresses
    score += 12.0 * (pr / cap) * (pr / cap) * progress;

    // Last-chance bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: favor bins leaving room for the next item
    let ns = next_item_size as f64;
    if ns > 0.0 {
        if pr >= ns {
            score -= 10.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 6.0 * (ns - pr) / cap;
        }
    }

    // Mild preference for consolidating into existing bins vs new bin
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    } else {
        score -= 4.0 / (1.0 + open_bins_count as f64);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter)
    score += 0.3 * (mean_residual - pr);

    score
}

