    // Odd leftovers fragment more: small penalty scaled by fraction
    if post_residual % 10 != 0 && post_residual > 0 {
        score += 3.0 * (1.0 - frac);
    }

    // Integer-division threshold classes on post_residual
    let cls = post_residual / 25; // 0..=4 harmonic class
    score -= (cls as f64) * 2.5;

    // Lookahead coupling: if next item fits exactly in the post residual,
