        // opening fresh becomes more attractive
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= mean_residual * 0.3 + progress * 5.0;
    }

    // Mild preference to fill fuller bins when many bins are open
    score -= (frac) * (open_bins_count.min(20) as f64);

    score
}

