        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Combined lookahead: if this placement leaves residual exactly matching next item,
    // and the item itself nearly filled the bin, strongly reward the chain.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size && item_size >= bin_residual / 2 {
        score -= 12.0;
    }

    // Mean-residual coupling: when the fleet is broadly tight, prefer keeping residuals usable.
    if mean_residual > 0.0 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 && next_item_size > post_residual {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space is worse if the next item cannot use it.
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and penalize opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if few bins open or item is large.
        score += 5.0 + pressure * 2.0 - (item_size as f64 - 50.0) * 0.3;
    } else {
        score -= pressure.min(20.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (better fill).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // 2-step lookahead: reward when post_residual can host the next item exactly/nearly
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits here afterwards: strong reward, tighter match better
            score -= 25.0 - gap * 0.5;
        } else {
            // next item won't fit: penalize dead space proportional to gap
            score += gap * 0.3;
        }
    }

    // Compare residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Late in stream: consolidate more strongly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: penalize slightly so we only open when truly needed
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;

    // Dead-space penalty for the lookahead item (refined tiers)
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size . max (1) as f64 ;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0 ;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0 ;
        } else {
            score += 14.0 + dead_ratio * 9.0 ;
        }
    }

    // Best-fit pressure with non-linear fill term (tuned from best variant)
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual . max (1) as f64) ;
        score -= ratio * 7.0 + ratio * ratio * 6.8 ;
    }

    // Waste penalty with mild convexity (softer on tiny waste)
    let waste = bin_residual . saturating_sub (item_size) ;
    if waste > 0 {
        let w = waste as f64 ;
        score += if w < 6.0 { w * 0.3 } else { w . sqrt () * 1.45 } ;
    }

    // Exact-fill lookahead bonus (stronger, from best variant)
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 13.0 ;
    }
    // Near-miss lookahead
    if post_residual > next_item_size && post_residual <= next_item_size + 7 && next_item_size > 0 {
        score -= 3.5 - (post_residual - next_item_size) as f64 * 0.15 ;
    }
    // Chain lookahead
    if post_residual > next_item_size && next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
        score -= 4.0 ;
    }

    // New-bin arbitration with crowding pressure
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity . max (1) as f64) ;
        let crowding = (open_bins_count as f64) . ln () . max (0.0) ;
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5 ;
        } else {
            score -= 9.0 + tight * 12.0 ;
        }
        // Late-stream new bins are cheaper than fragmenting
        if step_index > total_items * 4 / 5 {
            score -= 6.0 ;
        }
    }

    // Scarcity coupling
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64 ;
        if slack >= 0.0 && slack < 12.0 {
            score += 9.0 - slack * 0.6 ;
        }
    }

    // Global compaction term, progress-scaled (slightly stronger)
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64 ;
        if dev > 0.0 {
            let progress = (step_index as f64) / (total_items . max (1) as f64) ;
            score -= dev * (0.18 + 0.18 * progress) ;
        }
    }

    // Late-stream exact-fill bonus (extended range, from best variant)
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0 ;
    }

    // Early tiny residual penalty
    if post_residual > 0 && post_residual < 6 && step_index <= total_items / 2 {
        score += 3.5 ;
    }

    // Late-stream squeeze: prefer near-full bins when nearing the end
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4 ;
    }

    // Fragmentation guard
    if open_bins_count > 8 && post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 5.0 ;
    }

    // Two-step lookahead: reserve bins whose residual fits the next item exactly (best variant weight)
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        score -= 2.0 ;
    }

    // Perfect-fill dominant bonus: near-exact fits are strongly preferred
    if post_residual > 0 && post_residual <= 2 {
        score -= 4.0 ;
    }

    // Mid-stream pairing: prefer bins that can host the next item with a small remainder
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && step_index < total_items * 3 / 5 {
        score -= 1.5 ;
    }

    // New: residual-homogeneity coupling — favor bins close to mean residual when scarcity is high
    if fitting_bins_count >= 3 && bin_residual < bin_capacity {
        let dev = (mean_residual - bin_residual as f64) . abs () ;
        if dev < 6.0 {
            score -= (6.0 - dev) * 0.35 ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual, penalize large dead space.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize very small post residuals only if they can't host typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - (slack as f64) / (bin_capacity as f64));
            if slack == 0 {
                score -= 20.0; // perfect chain fit
            }
        } else {
            // next item cannot follow into this bin; mild penalty scaled by waste
            score += 3.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // New-bin candidate handling: opening a fresh bin is attractive only when
    // existing bins would leave large unusable residuals or the item is large.
    if bin_residual == bin_capacity {
        // Base new-bin score: neutral-ish, slightly above a good fit.
        score += 4.0;
        // Early in stream, keep bins open (consolidate); later allow more openings.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * (1.0 - progress);
        // If many bins already open, discourage yet another one.
        score += 0.5 * open_bins_count as f64;
        // But if the item is large relative to capacity and mean residual is low,
        // opening a new bin may be the right call.
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score -= 15.0 * large_item * (1.0 - mean_residual / (bin_capacity as f64)).max(0.0);
        // If no open bin can fit (fitting_bins_count refers to open bins only),
        // the new bin must be used — make it very attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild reward for filling bins that are already mostly full (consolidation).
    let used_frac = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 4.0 * used_frac;

    // Penalize bins whose residual deviates strongly from mean residual
    // (keeps a balanced portfolio of residuals for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: gaps too small to be useful are worthless.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score += (11 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        score += (21 - post_residual) as f64 * 2.0;
    }

    // Fit-quality coupling: reward tight fills relative to remaining space.
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual.max(1) as f64);
        score -= ratio * 6.8 + ratio * ratio * 6.2;
    }

    // Waste penalty (non-linear).
    let waste = bin_residual.saturating_sub(item_size);
    if waste > 0 {
        let w = waste as f64;
        score += if w < 6.0 { w * 0.3 } else { w.sqrt() * 1.45 };
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        let crowding = (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5;
        } else {
            score -= 9.0 + tight * 12.0;
        }
        if step_index > total_items * 4 / 5 {
            score -= 6.0;
        }
        if fitting_bins_count > 2 && next_item_size > 0 && next_item_size <= post_residual.max(next_item_size) {
            score += 5.0;
        }
    }

    // Open-bin pressure.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward placements that leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        if post_residual == next_item_size {
            score -= 13.0;
        }
        let slack = post_residual as f64 - next_item_size as f64;
        if fitting_bins_count <= 2 && slack < 12.0 {
            score += 9.0 - slack * 0.6;
        }
        if slack > 0.0 && slack <= 3.0 {
            score -= 2.0;
        }
        if slack > 3.0 && slack <= 7.0 {
            score -= 3.5 - slack * 0.15;
        }
        if slack > 7.0 && slack <= 14.0 && post_residual < 30 {
            score -= (14.0 - slack) * 0.35;
        }
        // Two-item lookahead: chained perfect fits.
        let after = post_residual - next_item_size;
        if after == 0 {
            score -= 6.0;
        } else if after <= 2 {
            score -= 3.0;
        }
        // Triple-chained lookahead.
        if after >= 3 && after <= 12 && fitting_bins_count > 1 {
            score += after as f64 * 0.35;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0;
        } else {
            score += 14.0 + dead_ratio * 9.0;
        }
        let unusable = post_residual as f64 / next_item_size.max(1) as f64;
        if unusable < 0.35 {
            score += 18.0 * (0.35 - unusable);
        }
    }

    // Mean-residual coupling: prefer tighter bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference to fill older/tighter bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Late-stream small-residual bonuses.
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Residual-fraction fit term.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let frac = (item_size as f64) / (bin_residual as f64);
        if frac >= 0.9 {
            score -= 5.0;
        } else if frac < 0.25 {
            score += (0.25 - frac) * 22.0;
        }
    }

    // Late-stream consolidation.
    let remaining = total_items.saturating_sub(step_index);
    if remaining <= 12 && post_residual > 0 {
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity.max(1) as f64;
        score -= fill * 4.0;
    }

    // Slack-band sharpening.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 2.0 {
            score -= 2.5;
        } else if gap <= 5.0 {
            score -= 1.2;
        }
    }

    // Early-stream bin conservation.
    if bin_residual == bin_capacity && remaining > 40 && fitting_bins_count >= 1 {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        if tight < 0.35 {
            score += 6.0;
        }
    }

    // Mid-band dead-space penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 8.0 {
            score += (8.0 - shortfall) * 1.8;
        }
    }

    // Horizon-aware exact-fill escalation.
    if post_residual == 0 && remaining > 0 {
        let horizon = 1.0 - (remaining.min(60) as f64) / 60.0;
        score -= 60.0 + horizon * 40.0;
    }

    // Multi-fit competition.
    if next_item_size > 0 && fitting_bins_count > 1 && post_residual > 0 {
        let match_err = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            ((next_item_size - post_residual) as f64) * 2.5
        };
        score += match_err * 0.45;
    }

    // Dead-space ratio sharpening against global mean residual.
    if post_residual > 0 && fitting_bins_count > 1 {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.4 && pr < 15.0 {
            score += (15.0 - pr) * 0.9;
        } else if pr >= mean_residual * 0.9 {
            score -= 2.0;
        }
    }

    // Mid-stream tightness escalation.
    if remaining > 40 && remaining < total_items.saturating_sub(40) {
        let fill_frac = (bin_residual.saturating_sub(item_size)) as f64 / bin_capacity.max(1) as f64;
        if fill_frac < 0.08 {
            score -= 3.0;
        }
    }

    // Exact-next-fit escalation — chain reward scaled by competing bins.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 1 {
        score -= 4.0 + (fitting_bins_count.min(6) as f64) * 0.8;
    }

    // Stranded-gap guard — penalize unusable leftovers more where many items remain.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && remaining > 20 {
        score += ((20.min(remaining)) as f64) * 0.08;
    }

    // COMBINED: near-miss lookahead sharpening — reward slack bands just above
    // the next item size, with mild progress scaling.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 7.0 {
            score -= (7.0 - gap) * 0.55 * (1.0 + progress * 0.5);
        }
    }

    // COMBINED: tight-residual fill incentive — prefer bins whose post-residual
    // is small relative to capacity, scaled by remaining stream length.
    if post_residual > 0 && remaining > 30 {
        let pr = post_residual as f64;
        let tightness = pr / bin_capacity.max(1) as f64;
        if tightness < 0.12 {
            score -= (0.12 - tightness) * 30.0;
        }
    }

    // NEW MUTATION: exact post-residual kill — a placement that exactly consumes
    // the bin's residual is always optimal; reward it decisively, stronger late.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 + progress);
    }

    // NEW MUTATION: residual-doubling lookahead — if the next item could itself
    // leave a residual that fits a third item, prefer keeping that chain alive.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 20 {
            // mild reward for mid-band leftovers that may serve later small items
            score -= (20 - after) as f64 * 0.12;
        }
    }

    // NEW MUTATION: single-fit squeeze — when only one bin fits, prefer the one
    // whose post-residual stays closest to the mean (keeps future options open).
    if fitting_bins_count == 1 && post_residual > 0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score -= 3.0 / (1.0 + dev * 0.25);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits less aggressively (leave room for variety).
    // Late: strongly prefer minimal post_residual to seal bins.
    let tight = (pr / cap).powi(2);
    let coupling = tight * (1.0 + 2.5 * progress * progress);

    // Cubic term: heavily penalize medium dead space, mildly tolerate tiny residue.
    let cubic = (pr / cap).powi(3) * 40.0;

    // Perfect fit bonus.
    let mut score = pr as f64 + coupling + cubic;

    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin,
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = 1.0 - pr / cap;
        score -= 30.0 * fit_quality * (1.0 + progress);
    }

    // Lookahead: reward bins whose residue can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 8.0 * snug;
        } else {
            // Residue too small for next item: penalize wasted potential.
            score += 6.0 * (pr / cap);
        }
    }

    // New-bin candidate: baseline slightly above good existing fits,
    // becomes attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score = cap * (0.9 + 0.4 * progress) + 10.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on coarse
    // capacity fractions (quarter/half marks) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % (bin_capacity / 2) == 0 {
            score -= 12.0;
        } else if pr % (bin_capacity / 4) == 0 {
            score -= 7.0;
        } else if pr % (bin_capacity / 10) == 0 {
            score -= 3.0;
        }
        // Penalize dead space: leftover smaller than the smallest plausible item (1..=10)
        if pr < 10 {
            score += (10 - pr) as f64 * 2.5;
        }
    } else {
        // Perfect fill is ideal
        score -= 40.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if pr >= next_item_size {
            // exact match of leftover to next item is excellent
            if pr == next_item_size {
                score -= 25.0;
            } else {
                score -= 8.0;
                // harmonic match: leftover class compatible with next item size
                if (pr - next_item_size) % (bin_capacity / 4) == 0 {
                    score -= 4.0;
                }
            }
        } else {
            // next item cannot use this leftover -> penalize proportionally
            score += (next_item_size - pr) as f64 * 0.4;
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 30.0 - fragmentation * 40.0 - progress * 5.0;
        if item_size > bin_capacity / 2 {
            score -= 10.0; // big items deserve fresh bins
        }
    }

    // Mild preference for tight fits relative to bin state
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 6.0;

    // Tie-break by mean residual alignment: prefer bins near the mean (typical)
    score += ((bin_residual as f64 - mean_residual).abs() / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
