            score -= 9.0 - (bin_residual - pair) as f64 * 1.2;
        }
    }

    // Fragment-risk penalty: avoid residuals in hard-to-fill mid band.
    if post_residual > 0 && post_residual < 40 {
        let r = post_residual as f64;
        if r > 10.0 && r < 18.0 {
