        score -= 18.0; // near-perfect, unusable for most items
    } else if frac < 0.25 {
        score += 12.0; // dead space band (11..24): too small for most, too big to waste
    } else if frac < 0.5 {
        score -= 4.0;
    } else if frac < 0.75 {
        score -= 8.0;
    } else {
        score -= 2.0;
    }

    // Modulo arithmetic on post_residual: residuals congruent to useful sizes
    let mod_class = post_residual % 10;
    if mod_class == 0 {
        score -= 3.0; // round residual aligns with decade item sizes
    } else if mod_class <= 3 {
        score += 1.5;
    }

    // Lookahead coupling: does this residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bonus scaled by how tightly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 + 4.0 * (1.0 - slack / cap).min(1.0);
        } else {
            score += 5.0; // next item won't fit here; this bin becomes dead-ish
        }
    } else {
        // last item: prefer filling tightly
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = mean_residual / cap;
        // penalize opening new bins unless mean residual is low or many bins open
        score += 25.0 - 20.0 * (1.0 - crowd.min(1.0)) - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 40.0; // must open first bin
        }
    }

    // Mild preference for consolidating into fewer bins when many are open
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (frac * 2.0);

    score
}

