        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Mean-residual coupling: when the fleet is broadly tight, prefer keeping residuals usable.
    if mean_residual > 0.0 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 && next_item_size > post_residual {
        score += 4.0;
    }

    // Mid-stream two-step lookahead: reward residuals that can host the next item
    // with room to spare, but only when the fleet is not crowded.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let next_slack = (post_residual - next_item_size) as f64;
        if next_slack <= 15.0 && open_bins_count < 24 {
            score -= 4.0 * (1.0 - next_slack / 15.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual strongly favored).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() < 1.0 {
            score -= 45.0;
        } else if next <= post_residual as f64 && post_residual as f64 - next <= 10.0 {
            score -= 18.0;
        } else if next > post_residual as f64 && post_residual > 0 {
            // Next item cannot use this residual: dead-space penalty scaled by gap.
            score += ((next - post_residual as f64).min(40.0)) * 0.6;
        }
    }

    // Compare against mean residual: prefer bins below mean (tighter bins get used first).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64; // = capacity - item
        let mut new_bin_score = fit_quality * 0.5;
        if fitting_bins_count > 0 {
            // Only attractive if best existing fit would leave large waste.
            new_bin_score += 30.0;
        }
        if next_item_size > 0 && (next_item_size as f64 - fit_quality).abs() < 1.0 {
            new_bin_score -= 20.0; // new bin enables perfect next-item fit
        }
        // Early in stream, opening bins is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += progress * 15.0;
        score = score.min(score) + new_bin_score - fit_quality * 0.0;
        score = new_bin_score + 40.0; // baseline so new bin loses to good fits
        if fitting_bins_count == 0 {
            score = 0.0; // must open a bin
        }
    }

    // Mild penalty for very large dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty scaled by how badly the residual fails to host the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0;
        } else {
            score += 14.0 + dead_ratio * 9.0;
        }
    }

    // Prefer bins where the item fills a large fraction of the residual.
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual.max(1) as f64);
        score -= ratio * 6.8 + ratio * ratio * 6.2;
    }

    // Waste created by this placement.
    let waste = bin_residual.saturating_sub(item_size);
    if waste > 0 {
        let w = waste as f64;
        score += if w < 6.0 { w * 0.3 } else { w.sqrt() * 1.45 };
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: exact fit for next item.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Near-exact lookahead fit.
    if post_residual > next_item_size && post_residual <= next_item_size + 7 && next_item_size > 0 {
        score -= 3.5 - (post_residual - next_item_size) as f64 * 0.15;
    }

    // Very tight near-fit: small slack is precious.
    if post_residual > next_item_size && next_item_size > 0 && post_residual - next_item_size <= 3 {
        score -= 2.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        let crowding = (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5;
        } else {
            score -= 9.0 + tight * 12.0;
        }
        if step_index > total_items * 4 / 5 {
            score -= 6.0;
        }
    } else {
        score += open_bins_count as f64 * 0.5;
    }

    // Last-chance pressure: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // When few bins fit, discourage leaving a small slack for the next item.
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack >= 0.0 && slack < 12.0 {
            score += 9.0 - slack * 0.6;
        }
    }

    // Late-stream tightening: tiny residuals are nearly perfect fits late on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 25 {
        score += 10.0 * progress;
    }
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Combined lookahead: if this placement leaves residual exactly matching next item,
    // and the item itself nearly filled the bin, strongly reward the chain.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size && item_size >= bin_residual / 2 {
        score -= 12.0;
    }

    // Mean-residual coupling: when the fleet is broadly tight, prefer keeping residuals usable.
    if mean_residual > 0.0 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 && next_item_size > post_residual {
        score += 4.0;
    }

    // NEW: two-step lookahead chain reward — residual fits next item with tight slack,
    // amplifying best-heuristic's near-fit discount with progress awareness.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= (10.0 - slack) * 0.55 * (0.5 + progress);
        }
    }

    // NEW: penalize leaving residuals in the awkward mid-band that rarely fits
    // typical items, scaled by remaining stream length.
    if post_residual > 0 && post_residual < 60 && progress < 0.85 {
        let band = if post_residual < 15 { 0.0 } else if post_residual < 30 { 2.5 } else if post_residual < 45 { 4.5 } else { 3.0 };
        score += band * (1.0 - progress);
    }

    // NEW: reward conserving large residuals when many items remain (future capacity).
    let remaining = total_items.saturating_sub(step_index);
    if post_residual >= 50 && remaining > total_items / 10 {
        score -= 3.0;
    }

    // NEW: strengthen last-chance pressure when the sole fitting bin leaves a
    // tight-but-usable residual for the next item.
    if fitting_bins_count == 1 && next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 5 {
        score -= 8.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
