pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a bonus.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Penalize dead space that can't fit typical items (post_residual too small).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += fitting_bins_count as f64 * 2.0;
    }

    // New empty bin candidate: penalize early, reward late or when fits are scarce.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 - progress * 10.0 + (open_bins_count as f64) * 1.5;
        if fitting_bins_count == 1 && post_residual == 0 {
            score -= 100.0; // perfect fit into fresh bin
        }
    }

    // Prefer bins with residuals far from the mean (opportunistic consolidation).
    score -= (mean_residual - bin_residual as f64).abs() * 0.05;

    // Mild preference for fuller bins as stream progresses.
    score -= progress * (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // Slight noise-free exploration coupling between open bins and post residual.
    score += (open_bins_count as f64).ln().max(0.0) * post_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: post_residual normalized, polynomial in progress
    let pr_norm = pr / cap;
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep
    score += 18.0 * pr_norm * pr_norm * (1.0 - poly);
    score += 6.0 * pr_norm * poly * (1.0 - pr_norm);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - pr_norm).powi(3) * (8.0 + 14.0 * t);

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * t;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: penalize if next item can't use the resulting residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 5.0 * (1.0 - (ns / cap));
        } else {
            score += 6.0 * (ns - pr) / cap;
        }
    }

    // Mean residual divergence penalty
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Slight preference for consolidating into fewer bins
    score -= 1.5 / (open_bins_count as f64 + 1.0);

    score
}

