        let match_err = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            ((next_item_size - post_residual) as f64) * 2.5
        };
        score += match_err * 0.45;
    }

    // Dead-space ratio sharpening against global mean residual.
    if post_residual > 0 && fitting_bins_count > 1 {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.4 && pr < 15.0 {
            score += (15.0 - pr) * 0.9;
        } else if pr >= mean_residual * 0.9 {
            score -= 2.5;
        }
    }

    // Mid-stream tightness escalation.
    if remaining > 40 && remaining < total_items.saturating_sub(40) {
        let fill_frac = (bin_residual.saturating_sub(item_size)) as f64 / bin_capacity.max(1) as f64;
        if fill_frac < 0.08 {
            score -= 3.0;
        }
    }

    // Exact-next-fit escalation — chain reward scaled by competing bins.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 1 {
        score -= 4.0 + (fitting_bins_count.min(6) as f64) * 0.8;
    }

    // Stranded-gap guard — penalize unusable leftovers more where many items remain.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && remaining > 20 {
        score += ((20.min(remaining)) as f64) * 0.08;
    }

    // COMBINED: tight-residual fill incentive — prefer bins whose post-residual
    // is small relative to capacity, scaled by remaining stream length.
    if post_residual > 0 && remaining > 30 {
        let pr = post_residual as f64;
        let tightness = pr / bin_capacity.max(1) as f64;
        if tightness < 0.12 {
            score -= (0.12 - tightness) * 30.0;
        }
    }

    // NEW: near-exact fill coupling — strongly reward bins where the item
    // nearly exhausts the residual, sharpened late in the stream.
    if post_residual > 0 && bin_residual < bin_capacity {
        let used_frac = (item_size as f64) / (bin_residual.max(1) as f64);
        if used_frac >= 0.75 {
            score -= (used_frac - 0.75) * 14.0 * (1.0 + progress);
        }
    }

    // NEW: lookahead two-step chain — reward post-residuals that can host the
    // next item AND leave a small reusable remainder.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 4 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: 8 classes of capacity/8
    let class = post_residual / (bin_capacity / 8).max(1);
    let class_bonus = match class {
        0 => 120.0,               // near-perfect fit
        1 => 60.0,                // 1/8 slack - still useful for small items
        2 => 25.0,
        3 => 0.0,
        4 => -10.0,               // half-empty bin: mildly discouraged
        5 => -20.0,
        6 => -35.0,
        _ => -50.0,               // mostly empty: wasteful placement
    };
    score -= class_bonus;

    // Exact modulo alignment: leftover divisible by common item sizes
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 15.0; }
        else if pr % 5 == 0 { score -= 5.0; }
        else if pr < 10 { score += 30.0; }   // dead space below min item size
    }

    // Lookahead: does the next item fit the leftover?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 40.0;
            // integer-division threshold: leftover leaves a small unusable tail
            let tail = pr - next_item_size;
            if tail > 0 && tail < 10 { score += 20.0; }
        } else {
            score += 25.0;
        }
    } else {
        // last item: prefer tightest fit
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 { score -= 35.0; }
    else if fitting_bins_count > 1 { score += 3.0 * (fitting_bins_count as f64 - 1.0); }

    // Prefer filling bins that are already relatively full
    let fullness = (bin_capacity - bin_residual) as f64 / cap;
    score -= 20.0 * fullness;

    // Early stream: keep bins open (spread), late stream: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / cap);
    score -= 10.0 * progress;

    // New-bin candidate handling: only attractive if nothing fits well
    if bin_residual == bin_capacity {
        score += 90.0; // default penalty: prefer existing bins
        if fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.5 {
            score -= 100.0; // opening a fresh bin is better than a poor squeeze
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;

    // Dead-space penalty for the lookahead item (refined tiers)
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size . max (1) as f64 ;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0 ;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0 ;
        } else {
            score += 14.0 + dead_ratio * 9.0 ;
        }
    }

    // Best-fit pressure with non-linear fill term (stronger quadratic, from best variant)
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual . max (1) as f64) ;
        score -= ratio * 6.8 + ratio * ratio * 6.2 ;
    }

    // Waste penalty with mild convexity (softer on tiny waste)
    let waste = bin_residual . saturating_sub (item_size) ;
    if waste > 0 {
        let w = waste as f64 ;
        score += if w < 6.0 { w * 0.3 } else { w . sqrt () * 1.45 } ;
    }

    // Exact-fill lookahead bonus
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 14.0 ;
    }
    // Near-miss lookahead
    if post_residual > next_item_size && post_residual <= next_item_size + 7 && next_item_size > 0 {
        score -= 3.5 - (post_residual - next_item_size) as f64 * 0.15 ;
    }
    // Chain lookahead
    if post_residual > next_item_size && next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
        score -= 4.0 ;
    }

    // New-bin arbitration with crowding pressure
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity . max (1) as f64) ;
        let crowding = (open_bins_count as f64) . ln () . max (0.0) ;
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5 ;
        } else {
            score -= 9.0 + tight * 12.0 ;
        }
        // Late-stream new bins are cheaper than fragmenting
        if step_index > total_items * 4 / 5 {
            score -= 6.0 ;
        }
    }

    // Scarcity coupling
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64 ;
        if slack >= 0.0 && slack < 12.0 {
            score += 9.0 - slack * 0.6 ;
        }
    }

    // Global compaction term, progress-scaled (stronger for compaction)
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64 ;
        if dev > 0.0 {
            let progress = (step_index as f64) / (total_items . max (1) as f64) ;
            score -= dev * (0.22 + 0.20 * progress) ;
        }
    }

    // Late-stream exact-fill bonus (extended range)
    if post_residual > 0 && post_residual <= 5 && step_index > total_items * 2 / 3 {
        score -= 7.0 ;
    }

    // Early tiny residual penalty
    if post_residual > 0 && post_residual < 6 && step_index <= total_items / 2 {
        score += 3.5 ;
    }

    // Late-stream squeeze: prefer near-full bins when nearing the end
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4 ;
    }

    // Fragmentation guard
    if open_bins_count > 8 && post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 5.0 ;
    }

    // Two-step lookahead: reserve bins whose residual fits the next item exactly
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        score -= 2.5 ;
    }

    // Perfect-fill dominant bonus: near-exact fits are strongly preferred
    if post_residual > 0 && post_residual <= 2 {
        score -= 4.0 ;
    }

    // Mid-stream pairing: prefer bins that can host the next item with a small remainder
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && step_index < total_items * 3 / 5 {
        score -= 1.5 ;
    }

    // NEW: residual-aware fill preference — reward leaving a residual close to the
    // mean residual of open bins (keeps future fits viable, reduces dead space)
    if post_residual > 0 {
        let pr = post_residual as f64 ;
        let gap = (pr - mean_residual . max (1.0)) . abs () ;
        if gap < 8.0 {
            score -= (8.0 - gap) * 0.55 ;
        }
    }

    // NEW: mid-stream large-residual preservation — avoid burning big residuals on
    // small items when the next item is also small (keeps flexibility)
    if post_residual > 40 && next_item_size > 0 && next_item_size < 25 && step_index < total_items * 2 / 3 {
        score += (post_residual as f64 - 40.0) * 0.12 ;
    }

    // NEW: late-stream aggressive compaction — strongly prefer the fullest bins
    if step_index > total_items * 3 / 5 && post_residual > 0 {
        let pr = post_residual as f64 ;
        if pr <= 20 {
            score -= (20.0 - pr) * 0.35 ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are pure loss; residuals below a usable threshold
    // (<= 10, the smallest typical item) are heavily penalized dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    } else if post_residual > 20 && post_residual <= 40 {
        score += 2.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Exact match with lookahead item: reserve this bin for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Avoid leaving a gap that exactly matches nothing useful while the
    // next item would fit here instead.
    if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few bins, mild pressure too.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Relative tightness: reward placing into bins whose residual is close
    // to the item size (tight fit) rather than a huge bin.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a straggler bin; consolidate into it.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0 + (item_size as f64).max(1.0).ln() * 4.0;
        // If several bins fit, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // Late in the stream, avoid leaving many partially-filled bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

