    // Lookahead: dead space relative to the NEXT item is the real waste.
    if pr > 0 && next_item_size > 0 && pr < next_item_size {
        let dead_ratio = (next_item_size - pr) as f64 / next_item_size.max(1) as f64;
        if pr < 22 {
