    // Exact next-item match reward.
    if pr > 0 && next_item_size > 0 && pr == next_item_size {
        score -= 13.0;
    }
    // Near-match: next item almost fills the gap.
    if pr > next_item_size && pr <= next_item_size + 7 && next_item_size > 0 {
        score -= 3.5 - (pr - next_item_size) as f64 * 0.15;
    }

    // Open-bin pressure: discourage scattering across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: open only when all open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        let crowding = (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5;
        } else {
