        }
        if step_index > total_items * 4 / 5 {
            score -= 6.0;
        }
    }

    // Late-stage: prefer closing bins near-perfectly.
    if pr > 0 && pr <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0;
    }
    if pr > 0 && pr <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - pr) as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect 2-chain), reward near matches.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            score -= 60.0; // perfect two-item chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer small slack after the hypothetical next placement
            score -= (20.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
        } else {
            // Next item can't follow in this bin: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + 10.0 * (gap / bin_capacity as f64);
        }
    }

    // Penalize post_residual that is small but unusable (dead space below min size 1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: bins far below mean are already tight,
    // using them keeps spread-out slack available elsewhere.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Early in the stream, prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * open_bins_count as f64 * (1.0 - progress);

    // Mild preference for tighter bins overall
    score += 0.1 * (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

