pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let fit_ratio = post_residual as f64 / cap;
    score -= (1.0 - fit_ratio).powi(3) * 30.0;

    // Penalize dead space that likely cannot be reused: post_residual < 10 is perfect,
    // but residuals between 1..10 are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: bonus if next item fits exactly in the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64) / cap;
        } else {
            // next item won't fit here; penalize leaving a gap close to next_item_size
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 6.0 * (1.0 - gap / next_item_size as f64);
            }
        }
    }

    // Last-chance bonus: only one bin fits the item; strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current bin fit is poor. Give the empty bin a moderate baseline score
    // that scales with stream progress (later in the stream, prefer consolidation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 18.0 + 22.0 * progress - (open_bins_count as f64).ln() * 4.0;
    }

    // Global pressure: many open bins with high mean residual -> encourage
    // filling existing bins rather than spreading.
    if bin_residual != bin_capacity {
        score -= (mean_residual / cap) * 5.0;
        score += open_bins_count as f64 * 0.5;
    }

