        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // prefer bins where next item leaves a "clean" residue again
            let chain_res = post_residual - next_item_size;
            if chain_res % 10 == 0 {
                score -= 15.0;
            }
            // fraction of residual consumed by lookahead
            score -= 25.0 * (nxt / pr);
        } else {
            // next item cannot follow here; residual likely stranded
            score += 15.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits: scale score down
        // relatively by fill fraction of this bin.
        let fill_frac = 1.0 - pr / cap;
        score -= 30.0 * fill_frac;
    }

    // New-bin candidate handling: only open a new bin if current bins are
    // all quite full (mean residual low) or too many bins are open with
    // fragmented residuals.
    if bin_residual == bin_capacity {
        // brand-new bin: neutral baseline, slight penalty so we prefer
        // reusing unless reuse is bad.
        score = cap * 0.5;
        let mean_r = mean_residual;
        if mean_r < cap * 0.25 {
            // open bins are nearly full -> new bin is fine
            score -= 50.0;
        }
        if open_bins_count > 0 && fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere, must open
        }
        // early stream: slightly prefer consolidating into few bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        return score;
    }

    // Prefer bins whose residual is far below mean (using space where it's abundant).
    if (pr - mean_residual).abs() < 1.0 {
        score += 5.0;
    }

    score
}

