    } else {
        // Penalize dead space that likely cannot be reused (items >= 10).
        if post_residual < 10 {
            score += 25.0;
        }
        score += (post_residual as f64).powf(1.35) * 0.06;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
