            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild preference for tighter bins among many candidates (already via post_residual).
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Brand-new bin candidate: only attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early on, opening bins is cheap; late, prefer filling existing bins.
        let open_penalty = 20.0 + 40.0 * progress;
        let value = open_penalty - 0.15 * open_bins_count as f64 - 0.05 * mean_residual;
        score += value + 0.02 * fragmentation;
    }

    // Global state coupling: high mean residual means bins are loose; tighten preference.
    score += 0.04 * (mean_residual - post_residual as f64).max(0.0);

    // Progression: as the stream advances, be greedier about exact packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

