    if bin_residual as f64 == cap {
        score += 1.0 + 0.5 * mean_residual / cap + 0.3 * (open_bins_count as f64).sqrt();
        // Early stream: prefer opening new bins slightly more.
        score -= 0.6 * (1.0 - progress);
