    // Dead-space penalty for the lookahead item (refined tiers)
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size . max (1) as f64 ;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0 ;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0 ;
        } else {
            score += 14.0 + dead_ratio * 9.0 ;
        }
    }

    // Best-fit pressure with non-linear fill term (combined strength)
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual . max (1) as f64) ;
        score -= ratio * 7.0 + ratio * ratio * 6.8 ;
    }

    // Waste penalty with mild convexity (softer on tiny waste)
    let waste = bin_residual . saturating_sub (item_size) ;
    if waste > 0 {
        let w = waste as f64 ;
        score += if w < 6.0 { w * 0.3 } else { w . sqrt () * 1.45 } ;
    }

    // Exact-fill lookahead bonus
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 14.0 ;
    }
    // Near-miss lookahead
    if post_residual > next_item_size && post_residual <= next_item_size + 7 && next_item_size > 0 {
        score -= 3.5 - (post_residual - next_item_size) as f64 * 0.15 ;
    }
    // Chain lookahead
    if post_residual > next_item_size && next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
        score -= 4.0 ;
    }

    // New-bin arbitration with crowding pressure and mean-dead-space coupling
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity . max (1) as f64) ;
        let crowding = (open_bins_count as f64) . ln () . max (0.0) ;
        let mean_dead = mean_residual . max (0.0) ;
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5 + mean_dead * 0.08 ;
        } else {
            score -= 9.0 + tight * 12.0 ;
        }
        // Late-stream new bins are cheaper than fragmenting
        if step_index > total_items * 4 / 5 {
            score -= 6.0 ;
        }
    }

    // Scarcity coupling
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64 ;
        if slack >= 0.0 && slack < 12.0 {
            score += 9.0 - slack * 0.6 ;
        }
    }

    // Global compaction term, progress-scaled (slightly stronger)
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64 ;
        if dev > 0.0 {
            let progress = (step_index as f64) / (total_items . max (1) as f64) ;
            score -= dev * (0.18 + 0.18 * progress) ;
        }
    }

    // Late-stream exact-fill bonus (extended range)
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0 ;
    }

    // Early tiny residual penalty
    if post_residual > 0 && post_residual < 6 && step_index <= total_items / 2 {
        score += 3.5 ;
    }

    // Late-stream squeeze: prefer near-full bins when nearing the end
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4 ;
    }

    // Fragmentation guard
    if open_bins_count > 8 && post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 5.0 ;
    }

    // Two-step lookahead: reserve bins whose residual fits the next item exactly
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        score -= 2.0 ;
    }

    // Perfect-fill dominant bonus: near-exact fits are strongly preferred
    if post_residual > 0 && post_residual <= 2 {
        score -= 4.0 ;
    }

    // Mid-stream pairing: prefer bins that can host the next item with a small remainder
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && step_index < total_items * 3 / 5 {
        score -= 1.5 ;
    }

    // NEW: residual-vs-next-item harmonic fit — reward bins whose post-residual
    // matches the next item's size class closely (fine-grained coupling)
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64 ;
        score -= (next_item_size as f64) . max (1.0) . ln () * 1.2 / (1.0 + gap * 0.35) ;
    }

    // NEW: triple-fit anticipation — bins that fit both next item and leave
    // usable residue get a compaction nudge mid-stream
    if next_item_size > 0 && post_residual >= next_item_size {
        let twice = post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 12 ;
        if twice && step_index > total_items / 4 && step_index < total_items * 3 / 4 {
            score -= 2.5 ;
        }
    }

    // NEW: discourage opening bins when a decent fit exists and stream is dense
    if bin_residual == bin_capacity && fitting_bins_count >= 1 {
        let density = (total_items . max (1) as f64) . ln () ;
        if item_size <= bin_capacity / 3 && open_bins_count > 3 {
            score += 3.0 + density * 0.4 ;
        }
    }

    // NEW: variance-aware waste shaping — penalize mid-range waste more when
    // residual spread is low (uniform stream => exact fits achievable)
    if waste > 8 && waste < 40 && mean_residual > 0.0 {
        let spread = (mean_residual - (waste as f64)) . abs () ;
        if spread < 15.0 {
            score += (40 - waste) as f64 * 0.12 ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 classify "dead space" quality.
    let class = (post_residual % 10) as f64;
    score += class * 0.35;

    // Perfect / near-perfect fits strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score += 12.0; // awkward leftover zone
    }

    // Integer division thresholds: post_residual in [1..=25] is "third-class" space.
    let third = post_residual / 25;
    match third {
        0 => score -= 8.0,   // very small residual: good packing
        1 => score += 5.0,   // medium residual
        _ => score += 15.0,  // large residual: bin still mostly empty
    }

    // Capacity fraction coupling: how much of the bin is consumed.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize leaving large unusable gap
            score += (post_residual as f64).min(next_item_size as f64) * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 30.0 * (1.0 - progress) - mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
    }

    // Mild pressure against bin sprawl.
    score += open_bins_count as f64 * 0.15;

    score
}

