pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // Penalize post_residual that falls into an "unusable" band (too small for
    // typical future items, i.e. below a minimum useful threshold).
    let min_useful: f64 = 10.0;
    if (post_residual as f64) < min_useful && post_residual > 0 {
        score += (min_useful - post_residual as f64) * 8.0;
    }

    // Reward tight fits: small post_residual generally good, but zero (perfect fit) is best.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // favor filling existing ones (especially the new-bin candidate gets penalized).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless it looks genuinely better.
        score += pressure * 4.0;
    } else {
        // Slight reward for using existing bins, scaled by open-bin count.
        score -= pressure.min(20.0);
    }

    // Lookahead coupling: if next item could use the post_residual, reward leaving it.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
