        if open_fit_pressure > 0.0 {
            new_bin_score += 10.0 * frac_waste;
        }
        // Early in the stream, prefer consolidating; late, opening new bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += 8.0 * (1.0 - progress);
        // Many open bins with slack: reuse them.
        new_bin_score += 0.15 * open_bins_count as f64;
        // If mean residual is high, open bins have room; penalize new bin.
        new_bin_score += 0.08 * mean_residual;
        // Exact-fit bonus for new bin (perfect single-item packing).
        if item_size == bin_capacity {
            new_bin_score -= 50.0;
        }
        score = new_bin_score + frac_waste;
    }

    // Mild global congestion: when many bins are open, prefer reuse (empty-bin calls already handled).
    if bin_residual != bin_capacity {
        score -= 0.02 * open_bins_count as f64;
    }

    score
}

