    if open_bins_count > 8 && post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 5.0 ;
    }

    // Two-step lookahead: reserve bins whose residual fits the next item exactly
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        score -= 2.0 ;
    }

    // Perfect-fill dominant bonus: near-exact fits are strongly preferred
    if post_residual > 0 && post_residual <= 2 {
        score -= 4.0 ;
    }

    // Mid-stream pairing: prefer bins that can host the next item with a small remainder
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && step_index < total_items * 3 / 5 {
        score -= 1.5 ;
    }

    // NEW: tighter mid-stream pairing band with exact-fit emphasis
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 && step_index >= total_items * 3 / 5 {
        score -= 2.5 ;
    }

    // NEW: density-aware compaction — reward bins already well below mean residual
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64 ;
        if dev > 8.0 {
            let progress = (step_index as f64) / (total_items . max (1) as f64) ;
            score -= (dev - 8.0) * 0.12 * (0.5 + progress) ;
        }
    }

    // NEW: triple-fit lookahead — bin that can host next item twice
    if next_item_size > 0 && post_residual >= 2 * next_item_size && 2 * next_item_size > 0 {
        score -= 3.0 ;
    }

    // NEW: late-stream new-bin tightening — discourage opening bins for small items late
    if bin_residual == bin_capacity && item_size < 40 && step_index > total_items / 2 {
        score += 6.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual, smoothly damped by progress (late stream -> tighter packing)
    let mut score = pr * (1.0 + 0.6 * progress);

    // Non-linear polynomial coupling: penalize mid-range dead space quadratically,
    // reward very small residuals (near-perfect fit) and large residuals (flexible bins)
    score += 30.0 * x * (1.0 - x) * (1.0 + progress);

    // Reward low post-residual (tight fit) with a smooth cubic term
    score -= 12.0 * (1.0 - x) * (1.0 - x) * (1.0 - x) * cap * 0.1;

    // Lookahead coupling: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let fit_ratio = n / pr.max(1.0);
            score -= 8.0 * fit_ratio * (1.0 - fit_ratio);
        } else {
            score += 6.0 * (1.0 - pr / n);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly early, more later (prefer reuse as stream grows)
    if bin_residual == bin_capacity {
        score += 15.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        // Mild reward for keeping bin count low
        score -= 1.0 / (1.0 + open_bins_count as f64);
    }

    // Coupling with mean residual: prefer bins deviating below mean (consolidate waste)
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worst when it falls
    // into "unusable" residue classes (small nonzero slivers).
    let pr = post_residual as i64;
    if pr > 0 && pr < 10 {
        // Tiny unusable sliver: heavy penalty (dead space).
        score += 60.0 - pr as f64;
    } else if pr == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Reward post_residuals that are harmonic with common item sizes
        // (divisible by 10, 20, 25, 50) => likely reusable.
        if pr % 10 == 0 { score -= 15.0; }
        if pr % 20 == 0 { score -= 5.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 5.0; }
        // Penalize awkward classes (prime-ish residues near small values).
        let r = pr % 30;
        if r > 0 && r < 10 { score += (10 - r) as f64 * 1.5; }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 { score -= 25.0; } else { score -= 5.0; }
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot class.
            score += ((next_item_size - post_residual) % 20) as f64 * 0.5;
        }
    } else {
        // Last item: prefer filling as much as possible.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when current
    // fits are poor. Penalize opening a new bin unless post_residual is large.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin, modulated by stream progress
        // and how many bins are already open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 70.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is natural.
        if item_size >= bin_capacity / 2 { score -= 25.0; }
        // If no other bin fits (fitting_bins_count==0 for open bins), reduce cost.
        if fitting_bins_count == 0 { score -= 60.0; }
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is a "tight" bin — prefer packing it to consolidate waste.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev.min(50.0) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty scaled by how badly the residual fails to host the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0;
        } else {
            score += 14.0 + dead_ratio * 9.0;
        }
    }

    // Prefer bins where the item fills a large fraction of the residual.
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual.max(1) as f64);
        score -= ratio * 7.2 + ratio * ratio * 6.5;
    }

    // Waste created by this placement.
    let waste = bin_residual.saturating_sub(item_size);
    if waste > 0 {
        let w = waste as f64;
        score += if w < 6.0 { w * 0.3 } else { w.sqrt() * 1.45 };
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: exact fit for next item.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 13.0;
    } else if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Near-exact lookahead fit.
    if post_residual > next_item_size && post_residual <= next_item_size + 7 && next_item_size > 0 {
        score -= 3.5 - (post_residual - next_item_size) as f64 * 0.15;
    }

    // Very tight near-fit: small slack is precious.
    if post_residual > next_item_size && next_item_size > 0 && post_residual - next_item_size <= 3 {
        score -= 2.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity.max(1) as f64);
        let crowding = (open_bins_count as f64).ln().max(0.0);
        let mean_dead = mean_residual.max(0.0);
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5 + mean_dead * 0.08;
        } else {
            score -= 9.0 + tight * 12.0;
        }
        if step_index > total_items * 4 / 5 {
            score -= 6.0;
        }
    } else {
        score += open_bins_count as f64 * 0.5;
    }

    // Last-chance pressure: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // When few bins fit, discourage leaving a small slack for the next item.
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack >= 0.0 && slack < 12.0 {
            score += 9.0 - slack * 0.6;
        }
    }

    // Late-stream tightening: tiny residuals are nearly perfect fits late on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 25 {
        score += 10.0 * progress;
    }
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Combined lookahead: chain reward when residual matches next item after a large fill.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size && item_size >= bin_residual / 2 {
        score -= 12.0;
    }

    // Mean-residual coupling: when the fleet is broadly tight, prefer keeping residuals usable.
    if mean_residual > 0.0 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 && next_item_size > post_residual {
        score += 4.0;
    }

    // Mid-band residual shaping — keep residuals in a reusable window for the next item.
    if post_residual > 0 && next_item_size > 0 {
        let slack = (post_residual as f64 - next_item_size as f64).max(0.0);
        if slack < 25.0 {
            score -= (25.0 - slack) * 0.35;
        }
    }

    // Fleet-level pressure — when the fleet is tight, prefer the tightest hosts.
    let fleet_tightness = if open_bins_count > 0 { mean_residual / bin_capacity.max(1) as f64 } else { 0.0 };
    if post_residual > 0 && fleet_tightness < 0.35 {
        if post_residual > next_item_size && post_residual - next_item_size > 18 {
            score += (post_residual - next_item_size - 18) as f64 * 0.22;
        }
    }

    // Two-item lookahead chain — reward residuals that could host next item plus a small remainder.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 && after_next <= 6 && progress > 0.5 {
            score -= 2.5;
        }
    }

    // NEW: early-stream conservation — avoid burning large residuals early when plenty of items remain.
    if post_residual > 0 && progress < 0.35 && post_residual > 40 {
        score += (post_residual - 40) as f64 * 0.12;
    }

    // NEW: large-item anticipation — if the next item is big, keep residuals big enough for it.
    if next_item_size > 0 && next_item_size as f64 > 0.6 * bin_capacity.max(1) as f64 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // NEW: reward exact two-item chain when the fleet is crowded.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && open_bins_count > 8 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

