    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer bins already below mean residual (more space left than average).
    score += (post_residual as f64 - mean_residual) * 0.1;

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

