    // Core tight-fit reward: exponential penalty on post_residual waste.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward using bins that would otherwise leave awkward small residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space: too small for any item (min size 1..100, but tiny slivers are weak)
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let pressure = mean_residual / bin_capacity as f64;
    score -= pressure * 10.0;

    // Penalize opening a new bin when open bins can already fit the item,
    // scaled by how much slack the system has.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins are more acceptable early; late in the stream, consolidation wins.
        score += 18.0 * (1.0 - 0.5 * progress) + 0.5 * open_bins_count as f64;
        // But if existing fit is terrible (large post_residual elsewhere),
        // opening fresh can win: new bin's score is its own residual baseline.
        score -= pressure * 12.0;
    }

    // Time horizon: as the stream nears its end, favor tighter fills
    // (fewer chances to reuse partial bins later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // Prefer bins whose residual is close to the item (relative fit quality).
    let rel_fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= rel_fit * 12.0;

