    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + progress) + norm_post * progress * (1.0 - progress);
    score += 3.0 * poly;

    // Penalize tight fits late in the stream less, reward them more
    let tight = 1.0 - norm_post;
    score -= 2.0 * tight * tight * (0.5 + 0.5 * progress);

    // Dead-space penalty: small post residual that can't fit typical next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 4.0 * (nxt - post) / cap * (1.0 - progress);
        } else {
            score -= 1.5 * (1.0 - (post - nxt) / cap);
        }
    } else {
        // last item: prefer filling bins as fully as possible
        score -= 5.0 * tight;
    }

