    // Progress modulation: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - frac) * 15.0 * progress;

    // Mild congestion term: many open bins -> prefer filling existing ones.
    score += 0.5 * open_bins_count as f64;

    score
}

