        score -= 2.0 + (10 - post_residual) as f64 * 0.4;
    }

    // Mean-residual coupling: discourage dumping into an already-large gap.
    if post_residual > 0 && mean_residual > 0.0 && (post_residual as f64) > mean_residual * 1.6 {
        score += 3.0;
    }

    // Pair-anticipation: reward residuals that can host the next item plus
    // a small follow-up, favoring bins that keep useful chains alive.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size + 8 {
        let chain_slack = (post_residual - next_item_size) as f64;
        if chain_slack <= 30.0 {
            score -= 4.0 * (1.0 - chain_slack / 30.0);
        }
    }

    // Early-stream conservatism: avoid fragmenting space early.
    if step_index < total_items / 3 && post_residual > 0 && post_residual < item_size {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (smaller post_residual) is better.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // ---- Aggressive 2-step lookahead matching ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        if nxt <= post {
            // Next item can chain into this bin's residual.
            let gap = post - nxt;
            if gap == 0.0 {
                // PERFECT 2-step chain: post_residual exactly fits next item.
                score -= 60.0;
            } else if gap <= 10.0 {
                // Near-perfect chain: small leftover after next item.
                score -= 45.0 - 2.5 * gap;
            } else {
                // Loose chain: reward proportional to how much is consumed.
                score -= 20.0 * (nxt / post);
            }
            // Extra bonus if this bin is the ONLY option (avoid new bin).
            if fitting_bins_count == 1 {
                score -= 15.0;
            }
        } else {
            // Next item CANNOT fit in the residual -> dead space risk.
            let dead = nxt - post;
            // Penalize dead space more when it is small-but-useless
            // (blocking a chain that almost worked).
            if dead <= 15.0 {
                score += 25.0 + 2.0 * (15.0 - dead);
            } else {
                score += 10.0;
            }
        }
    }

    // ---- Mean residual coupling ----
    // Favor bins whose residual is below the mean (consolidating tight bins),
    // penalize draining already-tight bins below mean.
    if (post_residual as f64) < mean_residual {
        score -= 8.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 4.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Empty bin: only attractive when no open bin offers a good 2-step chain.
        // Make it expensive unless the item is large relative to capacity.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: no open bin fits
        }
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            // Opening fresh keeps flexibility for the next item.
            score -= 10.0;
        }
    }

    // ---- Last-chance bonus: avoid opening a bin when this is the only fit ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // ---- Stream progression: late in stream, be greedier about tight fits ----
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small tie-break noise-free deterministic jitter based on bin identity.
    score += ((bin_residual as f64 * 0.017).sin()) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small, unusable remnants).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post-residual, reward chaining placements.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would exactly fill post-residual, extra reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // If next item cannot fit anywhere well and post_residual is large, mild penalty
    // for wasting a big residual now.
    if next_item_size > post_residual && post_residual > 30 {
        score += 5.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 35.0;
        // If current bin would be a tight fit, opening new bin is less attractive.
        if fit_ratio > 0.7 {
            score += 20.0;
        }
        // Many open bins with high mean residual: reuse is preferable.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 15.0;
        }
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Large item with no good home: new bin is fine.
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild preference for bins with residuals close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Fragmentation pressure: with many open bins, prefer filling the emptiest-ish
    // bins to consolidate.
    score += 0.02 * open_bins_count as f64 * (bin_capacity - bin_residual) as f64 / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) + 0.5 * x * x * x;
    let mut score = pr * (1.0 + poly * (1.0 + progress));

    // Penalize dead space more as stream progresses
    score += progress * x * x * cap * 0.3;

    // Reward tight fits smoothly (small post_residual)
    score -= (1.0 - x) * (1.0 - x) * item_size as f64 * 0.4;

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= fit_quality * fit_quality * 8.0 * (1.0 - progress * 0.5);
        } else {
            score += (nx - pr) / cap * 5.0;
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - x * x);
    }

    // Slight preference for bins with residuals near mean (balance)
    score += ((pr - mean_residual) / cap).abs() * 2.0;

    // Mild penalty for many open bins to discourage proliferation
    score += open_bins_count as f64 * 0.05 * x;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;

    // Dead-space penalty for the lookahead item (refined tiers)
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size . max (1) as f64 ;
        if post_residual < 22 {
            score += 54.0 + dead_ratio * 17.0 ;
        } else if post_residual < 32 {
            score += 24.0 + dead_ratio * 11.0 ;
        } else {
            score += 14.0 + dead_ratio * 9.0 ;
        }
    }

    // Best-fit pressure with non-linear fill term (combined strength)
    if item_size > 0 {
        let ratio = (item_size as f64) / (bin_residual . max (1) as f64) ;
        score -= ratio * 7.0 + ratio * ratio * 6.8 ;
    }

    // Waste penalty with mild convexity (softer on tiny waste)
    let waste = bin_residual . saturating_sub (item_size) ;
    if waste > 0 {
        let w = waste as f64 ;
        score += if w < 6.0 { w * 0.3 } else { w . sqrt () * 1.45 } ;
    }

    // Exact-fill lookahead bonus
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 14.0 ;
    }
    // Near-miss lookahead
    if post_residual > next_item_size && post_residual <= next_item_size + 7 && next_item_size > 0 {
        score -= 3.5 - (post_residual - next_item_size) as f64 * 0.15 ;
    }
    // Chain lookahead
    if post_residual > next_item_size && next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 6 {
        score -= 4.0 ;
    }

    // New-bin arbitration with crowding pressure and mean-dead-space coupling
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity . max (1) as f64) ;
        let crowding = (open_bins_count as f64) . ln () . max (0.0) ;
        let mean_dead = mean_residual . max (0.0) ;
        if fitting_bins_count > 1 && tight < 0.56 {
            score += 34.0 + (0.56 - tight) * 52.0 + crowding * 2.5 + mean_dead * 0.08 ;
        } else {
            score -= 9.0 + tight * 12.0 ;
        }
        // Late-stream new bins are cheaper than fragmenting
        if step_index > total_items * 4 / 5 {
            score -= 6.0 ;
        }
    }

    // Scarcity coupling
    if fitting_bins_count <= 2 && post_residual > 0 && next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64 ;
        if slack >= 0.0 && slack < 12.0 {
            score += 9.0 - slack * 0.6 ;
        }
    }

    // Global compaction term, progress-scaled (slightly stronger)
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64 ;
        if dev > 0.0 {
            let progress = (step_index as f64) / (total_items . max (1) as f64) ;
            score -= dev * (0.18 + 0.18 * progress) ;
        }
    }

    // Late-stream exact-fill bonus (extended range)
    if post_residual > 0 && post_residual <= 4 && step_index > total_items * 2 / 3 {
        score -= 7.0 ;
    }

    // Early tiny residual penalty
    if post_residual > 0 && post_residual < 6 && step_index <= total_items / 2 {
        score += 3.5 ;
    }

    // Late-stream squeeze: prefer near-full bins when nearing the end
    if post_residual > 0 && post_residual <= 10 && step_index > total_items * 4 / 5 {
        score -= 2.0 + (10 - post_residual) as f64 * 0.4 ;
    }

    // Fragmentation guard
    if open_bins_count > 8 && post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 5.0 ;
    }

    // Two-step lookahead: reserve bins whose residual fits the next item exactly
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        score -= 2.0 ;
    }

    // Perfect-fill dominant bonus: near-exact fits are strongly preferred
    if post_residual > 0 && post_residual <= 2 {
        score -= 4.0 ;
    }

    // Mid-stream pairing: prefer bins that can host the next item with a small remainder
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && step_index < total_items * 3 / 5 {
        score -= 1.5 ;
    }

    // NEW: fine-grained residual tiering — reward bins whose post-residual is a
    // "reusable" size (small enough to be likely fillable by future items)
    if post_residual > 0 {
        let pr = post_residual as f64 ;
        if pr <= 8.0 {
            score -= 1.2 + (8.0 - pr) * 0.22 ;
        } else if pr <= 16.0 {
            score -= 0.6 ;
        } else if pr > 40.0 && step_index < total_items / 2 {
            // large leftover early: mild penalty to keep bins tight
            score += (pr - 40.0) * 0.05 ;
        }
    }

    // NEW: combined fit-quality coupling — when many bins fit, demand tighter fits
    if fitting_bins_count > 4 && post_residual > 0 {
        let exactness = 1.0 - (post_residual as f64) / (bin_capacity . max (1) as f64) ;
        score -= exactness * 1.8 ;
    }

    // NEW: lookahead chain anticipation — bin that fits item + next item nearly fully
    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let chain_slack = (post_residual - item_size - next_item_size) as f64 ;
        if chain_slack <= 4.0 {
            score -= 3.0 - chain_slack * 0.5 ;
        }
    }

    score
}
